-- Navaratri Pooja, rebuilt from the book: the full Purvanga inlined, one
-- action and its words per screen. Generated by
-- scripts/build-navaratri-from-the-book.mjs; do not edit by hand.
--
-- Source: Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.1-26 and Navaratri Puja pp.286-304, read from
-- the page transcripts by book page and block. 112 steps replace 31:
-- First Day 109, Days 2 to 9 99, Vijayadashami 22.
-- The pooja, its modes, its namavalis, samagri and naivedyam are untouched.
-- See docs/plans/navaratri-rebuild-0062.md.

begin;

-- Re-runnable: the rite's steps are replaced wholesale. Archana rows go with
-- them by cascade.
delete from public.pooja_steps where pooja_id = 'navaratri_pooja';

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 1, 'purvangam', '{main,punar,udvasana}', 'Purvangam', 'பூர்வாங்கம்', 'Achamanam', 'ஆசமனம்',
        'Sit facing east or north. Fold the forefinger of the right hand against the thumb and curl the other three fingers so the palm holds one spoonful of water from the uddharani. Sip it once at each of the three names.',
        'கிழக்கு அல்லது வடக்கு நோக்கி அமரவும். வலது கையின் ஆள்காட்டி விரலைக் கட்டைவிரலுடன் சேர்த்து மடக்கி, மற்ற மூன்று விரல்களையும் குவித்து, உள்ளங்கையில் ஒரு உத்தரிணி ஜலம் நிற்கும்படி வைக்கவும். ஒவ்வொரு நாமத்திற்கும் ஒரு முறை அந்த ஜலத்தை அருந்தவும்.',
        'ॐ अच्युताय नमः ।
ॐ अनन्ताय नमः ।
ॐ गोविन्दाय नमः ।',
        'ஓம் அச்யுதாய நம꞉ ।
ஓம் அநந்தாய நம꞉ ।
ஓம் கோவிந்தாய நம꞉ ।',
        'oṃ acyutāya namaḥ ।
oṃ anantāya namaḥ ।
oṃ govindāya namaḥ ।',
        'Salutations to Achyuta, who never falls away; to Ananta, who has no end; to Govinda, who recovers what is lost.',
        'Three sips, three names, and the names are Vishnu''s: Achyuta, Ananta, Govinda. They are the same three whoever the pooja is for, because in Smartha practice every rite opens through Vishnu before it turns to its own deity. What the step does is mark a boundary. You were doing something else a minute ago; from here you are not.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.1, step 1, aachamanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 2, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Anga Vandanam', 'அங்க வந்தனம்',
        'With the right hand only, touch each place as you say its name: the thumb to the right and left cheek, the ring finger to the right and left eye, the index finger to the right and left nostril, the little finger to the right and left ear, the middle finger to the right and left shoulder. Then lay the whole palm on the navel and on the crown of the head. Reach across with the right hand for the left side.',
        'வலது கையால் மட்டும், ஒவ்வொரு நாமத்தைச் சொல்லும்போதும் அதற்குரிய இடத்தைத் தொடவும்: கட்டைவிரலால் வலது, இடது கன்னங்கள்; மோதிர விரலால் வலது, இடது கண்கள்; ஆள்காட்டி விரலால் வலது, இடது நாசிகள்; சுண்டு விரலால் வலது, இடது காதுகள்; நடுவிரலால் வலது, இடது தோள்கள். பின் முழு உள்ளங்கையால் நாபியையும் உச்சந்தலையையும் தொடவும். இடது பக்கத்தைத் தொட வலது கையைக் குறுக்காகக் கொண்டு செல்லவும்.',
        'केशव
नारायण
माधव
गोविन्द
विष्णो
मधुसूदन
त्रिविक्रम
वामन
श्रीधर
हृषीकेश
पद्मनाभ
दामोदर',
        'கேஶவ
நாராயண
மாதவ
கோவிந்த
விஷ்ணோ
மதுஸூதந
த்ரிவிக்ரம
வாமந
ஶ்ரீதர
ஹ்ருஷீகேஶ
பத்மநாப
தாமோதர',
        'keśava
nārāyaṇa
mādhava
govinda
viṣṇo
madhusūdana
trivikrama
vāmana
śrīdhara
hṛṣīkeśa
padmanābha
dāmodara',
        'Keshava, Narayana, Madhava, Govinda, Vishnu, Madhusudana, Trivikrama, Vamana, Shridhara, Hrishikesha, Padmanabha, Damodara: twelve names of Vishnu, said bare, one at each place the hand touches.',
        'Twelve names of Vishnu touched to twelve places, and again they are the same twelve in any Smartha pooja whichever god it is for. The body is being named part by part before it is asked to do anything. Nothing has been offered yet and no deity has been invited; this is still the karta getting ready.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.1-3, step 1, angavandanam; bare names as printed, each with its limb and finger');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 3, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Vighneshwara Dhyanam', 'விக்னேஸ்வர த்யானம்',
        'Make loose fists and gently tap both temples with the knuckles five times while reciting.',
        'இரு கைகளையும் லேசாக மடக்கி, விரல் முட்டிகளால் இரு நெற்றிப் பொட்டுகளிலும் மெதுவாக ஐந்து முறை குட்டியபடி சொல்லவும்.',
        'शुक्लाम्बरधरं विष्णुं शशिवर्णं चतुर्भुजं ।
प्रसन्न वदनं ध्यायेत् सर्व विघ्नोपशान्तये ॥',
        'ஶுக்லாம்பரதரம் விஷ்ணும் ஶஶிவர்ணம் சதுர்புஜம் ।
ப்ரஸந்ந வதநம் த்யாயேத் ஸர்வ விக்நோபஶாந்தயே ॥',
        'śuklāmbaradharaṃ viṣṇuṃ śaśivarṇaṃ caturbhujaṃ ।
prasanna vadanaṃ dhyāyet sarva vighnopaśāntaye ॥',
        'One should meditate on him who wears white, who pervades all, bright as the moon, four-armed, with a gracious face, so that every obstacle is quieted.',
        'The verse never says Ganesha. Shuklambaradharam vishnum shashivarnam chaturbhujam describes a white-robed, four-armed figure the colour of the moon, and different traditions read it as Ganesha or as Vishnu. What it asks for is unambiguous: sarva-vighna-upashantaye, the quieting of every obstacle, said before anything is attempted rather than after something has gone wrong.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.3, step 2, vighnEshvara dhyaanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 4, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Pranayamam', 'ப்ராணாயாமம்',
        'With the right hand, fold the index and middle fingers into the palm. Close the right nostril with the thumb and breathe in through the left on the first line; close the left nostril too with the ring and little fingers and hold through the second; open the right nostril and breathe out on the third. Then touch the right ear with the right hand.',
        'வலது கையில் ஆள்காட்டி விரலையும் நடுவிரலையும் உள்ளங்கையில் மடக்கவும். கட்டைவிரலால் வலது நாசியை மூடி, முதல் வரியைச் சொல்லியபடி இடது நாசி வழியாக மூச்சை இழுக்கவும்; மோதிர விரல், சுண்டு விரல்களால் இடது நாசியையும் மூடி, இரண்டாம் வரி முடியும் வரை மூச்சை நிறுத்தவும்; பின் வலது நாசியைத் திறந்து மூன்றாம் வரியைச் சொல்லியபடி மூச்சை வெளியிடவும். இறுதியில் வலது கையால் வலது காதைத் தொடவும்.',
        'ॐ भूः । ॐ भुवः । ओꣳ सुवः । ॐ महः । ॐ जनः । ॐ तपः । ओꣳ सत्यम् ।
ॐ तत्सवितुर्वरेण्यम् भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् ।
ओमापः ज्योतीरसः अमृतं ब्रह्म भूर्भुवस्सुवरोम् ॥',
        'ஓம் பூ꞉ । ஓம் புவ꞉ । ஓகும் ஸுவ꞉ । ஓம் மஹ꞉ । ஓம் ஜந꞉ । ஓம் தப꞉ । ஓகும் ஸத்யம் ।
ஓம் தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி । தியோ யோ ந꞉ ப்ரசோதயாத் ।
ஓமாப꞉ ஜ்யோதீரஸ꞉ அம்ருதம் ப்ரஹ்ம பூர்புவஸ்ஸுவரோம் ॥',
        'oṃ bhūḥ । oṃ bhuvaḥ । ogm suvaḥ । oṃ mahaḥ । oṃ janaḥ । oṃ tapaḥ । ogm satyam ।
oṃ tatsaviturvareṇyam bhargo devasya dhīmahi । dhiyo yo naḥ pracodayāt ।
omāpaḥ jyotīrasaḥ amṛtaṃ brahma bhūrbhuvassuvarom ॥',
        'Om, earth; Om, sky; Om, heaven; Om, the great world; Om, the world of beings; Om, the world of austerity; Om, the true. Om, we meditate on the adorable radiance of the divine Savitr; may he set our minds in motion. Om, the waters, the light, the essence, the immortal, Brahman: earth, sky and heaven, Om.',
        'The only step in the whole pooja that is about breathing rather than offering. The seven worlds, the Gayatri, then the line about water and light: it is a long thing to say on a held breath, and the length is the point. In this tradition women do not perform it, which is why the app removes the step for them rather than showing it greyed out.', 'filter_male_only', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.3-4, step 3, praaNaayaamaha; lines cut at the book''s Puraka, Kumbhaka and Rechaka marks');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 5, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Vighneshwara Sankalpam', 'விக்னேஸ்வர ஸங்கல்பம்',
        'Rest the left palm, facing up, on the right thigh and cross the right palm over it. Resolve to worship Vighneshwara first, so that the Navaratri pooja that follows reaches its end without obstacle. Wash the hands afterwards.',
        'இடது உள்ளங்கையை மேல்நோக்கியபடி வலது தொடையின் மேல் வைத்து, வலது உள்ளங்கையை அதன் மேல் குறுக்காக வைக்கவும். பின்வரும் நவராத்திரி பூஜை தடையின்றி நிறைவேற, முதலில் விக்னேஸ்வர பூஜை செய்வதாக ஸங்கல்பம் செய்யவும். பிறகு கைகளைக் கழுவவும்.',
        'ममोपात्त समस्त दुरितक्षयद्वारा श्री परमेश्वर प्रीत्यर्थं करिष्यमाणस्य
कर्मणः निर्विघ्नेन परिसमाप्त्यर्थं आदौ विघ्नेश्वर पूजां करिष्ये ।',
        'மமோபாத்த ஸமஸ்த துரிதக்ஷயத்வாரா ஶ்ரீ பரமேஶ்வர ப்ரீத்யர்தம் கரிஷ்யமாணஸ்ய
கர்மண꞉ நிர்விக்நேந பரிஸமாப்த்யர்தம் ஆதௌ விக்நேஶ்வர பூஜாம் கரிஷ்யே ।',
        'mamopātta samasta duritakṣayadvārā śrī parameśvara prītyarthaṃ kariṣyamāṇasya
karmaṇaḥ nirvighnena parisamāptyarthaṃ ādau vighneśvara pūjāṃ kariṣye ।',
        'For the pleasure of Parameshvara, through the destruction of all the sin I have accumulated, and so that the rite I am about to perform reaches its end without obstruction, I shall first worship Vighneshwara.',
        'The pooja resolves twice, and this is the first. It is worth noticing that the two resolves are not the same sentence: this one asks only that the rite about to begin reach its end without obstruction, and the one later asks for everything the household actually wants. Splitting them is a kind of honesty about sequence. You do not ask for prosperity while the road is still blocked; you clear the road, and then you ask.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.4, step 4, sankalpaha');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 6, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Sakala Devata Vandanam', 'ஸகல தேவதா வந்தனம்',
        'Join the palms and salute every deity, from the world of Brahma down to the Lokaloka mountain at the edge of the worlds. Nothing is offered here; it is a salutation made before the household rite begins.',
        'கைகளைக் கூப்பி, ப்ரம்மலோகம் முதல் உலகங்களின் எல்லையிலுள்ள லோகாலோக பர்வதம் வரை வாழும் அனைத்து தேவர்களையும் வணங்கவும். இங்கு எதுவும் சமர்ப்பிக்கப்படுவதில்லை; வீட்டுப் பூஜை தொடங்கும் முன் செய்யும் வணக்கம்.',
        'आब्रह्मलोकात् आशेषात् – आलोकालोकपर्वतात् ।
ये वसन्ति द्विजा देवाः तेभ्यो नित्यं नमो नमः ॥',
        'ஆப்ரஹ்மலோகாத் ஆஶேஷாத் – ஆலோகாலோகபர்வதாத் ।
யே வஸந்தி த்விஜா தேவா꞉ தேப்யோ நித்யம் நமோ நம꞉ ॥',
        'ābrahmalokāt āśeṣāt – ālokālokaparvatāt ।
ye vasanti dvijā devāḥ tebhyo nityaṃ namo namaḥ ॥',
        'To the twice-born and the gods who dwell everywhere, from the world of Brahma to the Lokaloka mountain, salutation again and again, always.',
        'Before the rite narrows to one deity it widens, once, to all of them — everything from the world of Brahma to the mountain at the edge of the worlds. It takes about four seconds and it is easy to treat as throat-clearing. It is not. A household pooja is a small, particular thing done in one room for one family, and this line places it inside something that is neither small nor particular before it begins.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.4, step 5, sakala dEvataa vandanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 7, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Deepa Pooja', 'தீப பூஜை',
        'Light the lamps facing east while reciting this. Then apply kumkumam to the base and the rim of the lamp and offer flowers and akshatai to it.',
        'கிழக்கு நோக்கி விளக்குகளை ஏற்றி இதைச் சொல்லவும். பிறகு விளக்கின் அடியிலும் விளிம்பிலும் குங்குமம் இட்டு, பூவும் அட்சதையும் சமர்ப்பிக்கவும்.',
        'दीपज्योतिः परं ब्रह्म दीपज्योतिर्जनार्दनः ।
दीपो हरतु मे पापम् दीपज्योतिर्नमोऽस्तु ते ॥',
        'தீபஜ்யோதி꞉ பரம் ப்ரஹ்ம தீபஜ்யோதிர்ஜநார்தந꞉ ।
தீபோ ஹரது மே பாபம் தீபஜ்யோதிர்நமோஸ்து தே ॥',
        'dīpajyotiḥ paraṃ brahma dīpajyotirjanārdanaḥ ।
dīpo haratu me pāpam dīpajyotirnamo''stu te ॥',
        'The light of the lamp is the supreme Brahman; the light of the lamp is Janardana. May the lamp take away my sin. Salutation to you, light of the lamp.',
        'The lamp is lit first and then worshipped in its own right, which is the tell. It is not illumination for the deity to be seen by; the verse calls the flame Brahman and Janardana outright. Light is the first guest, not the lighting.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.5, step 5, deepa mantraha');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 8, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Asana Pooja', 'ஆஸன பூஜை',
        'Sprinkle a little water on your seat while reciting this, sitting OUTSIDE the seat. Then take your place on it. The seat is consecrated before the karta occupies it, not after.',
        'ஆஸனத்திற்கு வெளியே அமர்ந்து, இதைச் சொல்லிக்கொண்டே ஆஸனத்தின் மீது சிறிது நீரைத் தெளிக்கவும். பிறகு அதில் அமரவும். பூஜை செய்பவர் அமருவதற்கு முன்பே ஆஸனம் சுத்தி செய்யப்படுகிறது.',
        'पृथ्वी त्वया धृता लोका देवि त्वं विष्णुना धृता ।
त्वं च धारय मां देवि पवित्रं कुरु च आसनम् ॥',
        'ப்ருத்வீ த்வயா த்ருதா லோகா தேவி த்வம் விஷ்ணுநா த்ருதா ।
த்வம் ச தாரய மாம் தேவி பவித்ரம் குரு ச ஆஸநம் ॥',
        'pṛthvī tvayā dhṛtā lokā devi tvaṃ viṣṇunā dhṛtā ।
tvaṃ ca dhāraya māṃ devi pavitraṃ kuru ca āsanam ॥',
        'Earth, by you the worlds are borne, and you yourself are borne by Vishnu. Bear me too, O Devi, and make this seat pure.',
        'You consecrate the seat while sitting outside it, and only then take your place. Every other upachara in the pooja is offered to someone else. This one is offered to the ground under yourself, and it is asked of the earth rather than of a god — bear me, and make this seat pure. The karta is prepared like an object in the rite, because that is what they are about to become.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.5, step 6, aasana poojaa');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 9, 'purvangam', '{main,punar,udvasana}', 'Purvangam', 'பூர்வாங்கம்', 'Ghanta Pooja', 'கண்டா பூஜை (மணி)',
        'Apply sandal paste to the handle of the bell, then ring it to welcome the deity.',
        'மணியின் கைப்பிடியில் சந்தனம் இட்டு, பின் தேவதையை வரவேற்க மணியை அடிக்கவும்.',
        'आगमार्थं तु देवानां गमनार्थं तु रक्षसाम् ।
घण्टारवं करोम्यादौ देवताह्वान लाञ्छनम् ॥',
        'ஆகமார்தம் து தேவாநாம் கமநார்தம் து ரக்ஷஸாம் ।
கண்டாரவம் கரோம்யாதௌ தேவதாஹ்வாந லாஞ்சநம் ॥',
        'āgamārthaṃ tu devānāṃ gamanārthaṃ tu rakṣasām ।
ghaṇṭāravaṃ karomyādau devatāhvāna lāñchanam ॥',
        'I first make the sound of the bell, for the coming of the gods and the going of the rakshasas: it is the sign by which the deities are called.',
        'One sound doing two opposite jobs: agamartham tu devanam, gamanartham tu rakshasam, for the coming of the gods and the going of what should not be here. It is also the only part of the pooja the rest of the house can hear from another room, which is how everyone knows it has begun.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.5, step 7, ghaNTaa poojaa');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 10, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Dhyanam (again)', 'விக்னேஸ்வர த்யானம் (மீண்டும்)',
        'The small Ganesha pooja begins with the same verse. Tap both temples five times with loose fists while reciting it.',
        'சிறிய விநாயகர் பூஜை இதே ஸ்லோகத்துடன் தொடங்குகிறது. லேசாக மடக்கிய கைகளால் இரு நெற்றிப் பொட்டுகளிலும் ஐந்து முறை குட்டியபடி சொல்லவும்.',
        'शुक्लाम्बरधरं विष्णुं शशिवर्णं चतुर्भुजं ।
प्रसन्नवदनं ध्यायेत् सर्व विघ्नोपशान्तये ॥',
        'ஶுக்லாம்பரதரம் விஷ்ணும் ஶஶிவர்ணம் சதுர்புஜம் ।
ப்ரஸந்நவதநம் த்யாயேத் ஸர்வ விக்நோபஶாந்தயே ॥',
        'śuklāmbaradharaṃ viṣṇuṃ śaśivarṇaṃ caturbhujaṃ ।
prasannavadanaṃ dhyāyet sarva vighnopaśāntaye ॥',
        'One should meditate on him who wears white, who pervades all, bright as the moon, four-armed, with a gracious face, so that every obstacle is quieted.',
        'The verse that opened the morning is said again because a new rite starts here, inside the larger one. The Vighneshwara pooja has its own beginning, and every beginning in the rite is marked the same way.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.6, step 8, vighnEshvara dhyaanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 11, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Avahanam', 'விக்னேஸ்வர ஆவாஹனம்',
        'Shape a small cone of turmeric mixed with water and set it before you. If you have learnt the Vedic intonation, say the first verse; otherwise begin at agajanana. Invite Vighneshwara into the turmeric and offer akshatai.',
        'மஞ்சளை ஜலத்தில் பிசைந்து சிறு கூம்பாகச் செய்து முன்னே வைக்கவும். வேத ஸ்வரத்துடன் கற்றவர்கள் முதல் மந்த்ரத்தைச் சொல்லவும்; மற்றவர்கள் "அகஜானன" என்பதிலிருந்து தொடங்கவும். மஞ்சளில் விக்னேஸ்வரரை ஆவாஹனம் செய்து அக்ஷதை சமர்ப்பிக்கவும்.',
        'ॐ गणानां त्वा गणपतिꣳ हवामहे कविं कवीनामुपमश्रवस्तमम् ।
ज्येष्ठराजं ब्रह्मणां ब्रह्मणस्पत आ नः शृण्वन्नूतिभिस्सीद सादनम् ॥
ॐ भूर्भुवस्सुवरोम् ॥
अगजानन पद्मार्कं गजाननं अहर्निशम्।
अनेकदन्तम् भक्तानां एकदन्तं उपास्महे॥
अस्मिन् हरिद्राबिम्बे विघ्नेश्वरं ध्यायामि, विघ्नेश्वरं आवाहयामि॥',
        'ஓம் கணாநாம் த்வா கணபதிகும் ஹவாமஹே கவிம் கவீநாமுபமஶ்ரவஸ்தமம் ।
ஜ்யேஷ்டராஜம் ப்ரஹ்மணாம் ப்ரஹ்மணஸ்பத ஆ ந꞉ ஶ்ருண்வந்நூதிபிஸ்ஸீத ஸாதநம் ॥
ஓம் பூர்புவஸ்ஸுவரோம் ॥
அகஜாநந பத்மார்கம் கஜாநநம் அஹர்நிஶம்।
அநேகதந்தம் பக்தாநாம் ஏகதந்தம் உபாஸ்மஹே॥
அஸ்மிந் ஹரித்ராபிம்பே விக்நேஶ்வரம் த்யாயாமி, விக்நேஶ்வரம் ஆவாஹயாமி॥',
        'oṃ gaṇānāṃ tvā gaṇapatigm havāmahe kaviṃ kavīnāmupamaśravastamam ।
jyeṣṭharājaṃ brahmaṇāṃ brahmaṇaspata ā naḥ śṛṇvannūtibhissīda sādanam ॥
oṃ bhūrbhuvassuvarom ॥
agajānana padmārkaṃ gajānanaṃ aharniśam।
anekadantam bhaktānāṃ ekadantaṃ upāsmahe॥
asmin haridrābimbe vighneśvaraṃ dhyāyāmi, vighneśvaraṃ āvāhayāmi॥',
        'We call on you, lord of the ganas, poet among poets, most renowned, eldest king of prayers, lord of sacred speech: hear us and take your seat with your protection. We worship day and night the single-tusked, elephant-faced one, sun to the lotus of Parvati''s face, who gives many gifts to his devotees. In this turmeric image I meditate on Vighneshwara and invoke him.',
        'Two invocations are printed and the karta takes the one they can say properly. The Vedic verse needs its accents right; the simpler verse needs only sincerity, and both bring the same Ganesha into the same pinch of turmeric.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.6-7, step 8, praarthanaa: the Vedic verse for those who know its intonation, and the verse for everyone else');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 12, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Asanam', 'விக்னேஸ்வர ஆஸனம்',
        'Offer a few grains of akshatai at the turmeric Ganesha as his seat.',
        'மஞ்சள் பிள்ளையாருக்கு ஆஸனமாகச் சில அக்ஷதைகளைச் சமர்ப்பிக்கவும்.',
        'विघ्नेश्वराय नमः आसनं समर्पयामि।',
        'விக்நேஶ்வராய நம꞉ ஆஸநம் ஸமர்பயாமி।',
        'vighneśvarāya namaḥ āsanaṃ samarpayāmi।',
        'Salutations to Vighneshwara: I offer a seat.',
        'The first courtesy to any guest is a place to sit. Akshatai stands in for the seat, as it will for anything the household does not have to hand.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.7, step 8, aasanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 13, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Padyam', 'விக்னேஸ்வர பாத்யம்',
        'Pour one uddharani of water into a cup, for washing his feet.',
        'பாதம் கழுவுவதற்காக ஒரு உத்தரிணி ஜலத்தை ஒரு கிண்ணத்தில் விடவும்.',
        'विघ्नेश्वराय नमः पाद्यं समर्पयामि ।',
        'விக்நேஶ்வராய நம꞉ பாத்யம் ஸமர்பயாமி ।',
        'vighneśvarāya namaḥ pādyaṃ samarpayāmi ।',
        'Salutations to Vighneshwara: I offer water for the feet.',
        'Water for the feet is what a traveller is given at the door. Ganesha is received into his cone of turmeric like someone who has walked a long way to come.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.7, step 8, paadyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 14, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Arghyam', 'விக்னேஸ்வர அர்க்யம்',
        'Pour one uddharani of water, with a little sandal, akshatai and a flower in it, into the cup as a welcome.',
        'சிறிது சந்தனம், அக்ஷதை, புஷ்பம் கலந்த ஒரு உத்தரிணி ஜலத்தை வரவேற்பாகக் கிண்ணத்தில் விடவும்.',
        'विघ्नेश्वराय नमः अर्घ्यं समर्पयामि।',
        'விக்நேஶ்வராய நம꞉ அர்க்யம் ஸமர்பயாமி।',
        'vighneśvarāya namaḥ arghyaṃ samarpayāmi।',
        'Salutations to Vighneshwara: I offer arghyam, the water of welcome.',
        'Arghyam is the honoured guest''s water, set apart by what is added to it. The sandal and the flower are what turn plain water into a welcome.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.7, step 8, arghyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 15, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Achamaniyam', 'விக்னேஸ்வர ஆசமனீயம்',
        'Pour one uddharani of water into the cup, for him to sip.',
        'அவர் அருந்துவதற்காக ஒரு உத்தரிணி ஜலத்தைக் கிண்ணத்தில் விடவும்.',
        'विघ्नेश्वराय नमः आचमनीयं समर्पयामि।',
        'விக்நேஶ்வராய நம꞉ ஆசமநீயம் ஸமர்பயாமி।',
        'vighneśvarāya namaḥ ācamanīyaṃ samarpayāmi।',
        'Salutations to Vighneshwara: I offer water to sip.',
        'The guest who has washed is given water to sip, as the karta sipped at the very start. The deity receives the same purifications the worshipper used on themselves.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.8, step 8, aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 16, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Snanam', 'விக்னேஸ்வர ஸ்நானம்',
        'Dip a flower in water and sprinkle a little over the turmeric Ganesha, as his bath.',
        'ஒரு புஷ்பத்தை ஜலத்தில் நனைத்து, மஞ்சள் பிள்ளையாரின் மேல் ஸ்நானமாகச் சிறிது தெளிக்கவும்.',
        'विघ्नेश्वराय नमः स्नानं समर्पयामि।',
        'விக்நேஶ்வராய நம꞉ ஸ்நாநம் ஸமர்பயாமி।',
        'vighneśvarāya namaḥ snānaṃ samarpayāmi।',
        'Salutations to Vighneshwara: I offer a bath.',
        'A cone of turmeric would dissolve under a real bath, so it is bathed with a flower dipped in water. The gesture is fitted to the image rather than dropped.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.8, step 8, snaanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 17, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Achamaniyam after Snanam', 'விக்னேஸ்வர ஸ்நானாநந்தர ஆசமனீயம்',
        'Pour one more uddharani of water into the cup, for sipping after the bath.',
        'ஸ்நானத்திற்குப் பின் அருந்துவதற்காக இன்னொரு உத்தரிணி ஜலத்தைக் கிண்ணத்தில் விடவும்.',
        'विघ्नेश्वराय नमः स्नानानन्तरं आचमनीयं समर्पयामि ।',
        'விக்நேஶ்வராய நம꞉ ஸ்நாநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி ।',
        'vighneśvarāya namaḥ snānānantaraṃ ācamanīyaṃ samarpayāmi ।',
        'Salutations to Vighneshwara: after the bath, I offer water to sip.',
        'Sipping water after bathing is ordinary good practice for anyone, and the rite keeps even this small courtesy in its place.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.8, step 8, snaanaanantaram aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
