values ('navaratri_pooja', 18, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Vastram', 'விக்னேஸ்வர வஸ்த்ரம்',
        'Offer a set of new clothes.',
        'புதிய வஸ்திரங்களைச் சமர்ப்பிக்கவும்.',
        'विघ्नेश्वराय नमः वस्त्रयुग्मम् समर्पयामि।',
        'விக்நேஶ்வராய நம꞉ வஸ்த்ரயுக்மம் ஸமர்பயாமி।',
        'vighneśvarāya namaḥ vastrayugmam samarpayāmi।',
        'Salutations to Vighneshwara: I offer a pair of garments.',
        'Vastrayugmam, a pair of cloths, upper and lower, as any guest would be given. Dressing the deity is the moment a visit becomes a stay.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.8, step 8, vastrayugmam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
