values ('navaratri_pooja', 19, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Upaveetam', 'விக்னேஸ்வர உபவீதம்',
        'Offer a new sacred thread.',
        'புதிய யஜ்ஞோபவீதம் சமர்ப்பிக்கவும்.',
        'विघ्नेश्वराय नमः यज्ञोपवीतम् समर्पयामि।',
        'விக்நேஶ்வராய நம꞉ யஜ்ஞோபவீதம் ஸமர்பயாமி।',
        'vighneśvarāya namaḥ yajñopavītam samarpayāmi।',
        'Salutations to Vighneshwara: I offer the sacred thread.',
        'Ganesha is given the yajnopavitam as one who keeps the Vedic rites, the same thread a boy receives at his upanayanam.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.8, step 8, yajnyOpaveetam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
