values ('navaratri_pooja', 20, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Gandham', 'விக்னேஸ்வர கந்தம்',
        'Anoint the turmeric Ganesha with sandal paste, then put turmeric and kumkumam over the sandal.',
        'மஞ்சள் பிள்ளையாருக்குச் சந்தனம் இட்டு, அதன் மேல் மஞ்சளும் குங்குமமும் இடவும்.',
        'विघ्नेश्वराय नमः गन्धान् धारयामि,
गन्धोपरि हरिद्रा कुङ्कुमम् समर्पयामि।',
        'விக்நேஶ்வராய நம꞉ கந்தாந் தாரயாமி,
கந்தோபரி ஹரித்ரா குங்குமம் ஸமர்பயாமி।',
        'vighneśvarāya namaḥ gandhān dhārayāmi,
gandhopari haridrā kuṅkumam samarpayāmi।',
        'Salutations to Vighneshwara: I apply sandal paste, and over the sandal I offer turmeric and kumkumam.',
        'Sandal first and colour on top of it, the order in which a forehead is dressed. One rubric covers both because it is one anointing.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.8, step 8, gandhaan dhaarayaami; one rubric for sandal and kunkum');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
