values ('navaratri_pooja', 21, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Abharanam', 'விக்னேஸ்வர ஆபரணம்',
        'Offer any ornament.',
        'ஏதேனும் ஒரு ஆபரணத்தைச் சமர்ப்பிக்கவும்.',
        'विघ्नेश्वराय नमः आभरणम् समर्पयामि।',
        'விக்நேஶ்வராய நம꞉ ஆபரணம் ஸமர்பயாமி।',
        'vighneśvarāya namaḥ ābharaṇam samarpayāmi।',
        'Salutations to Vighneshwara: I offer an ornament.',
        'Any ornament will do. What matters is not its worth but that nothing which honours a guest is left out.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.9, step 8, aabharaNam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
