values ('navaratri_pooja', 22, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Akshatai', 'விக்னேஸ்வர அக்ஷதை',
        'Offer akshatai.',
        'அக்ஷதை சமர்ப்பிக்கவும்.',
        'विघ्नेश्वराय नमः अक्षतान् समर्पयामि ।',
        'விக்நேஶ்வராய நம꞉ அக்ஷதாந் ஸமர்பயாமி ।',
        'vighneśvarāya namaḥ akṣatān samarpayāmi ।',
        'Salutations to Vighneshwara: I offer unbroken rice.',
        'Akshata means unbroken. Grain that has not been split is the simplest whole thing a household has, offered as a sign that the worship is meant whole.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.9, step 8, akSHataan');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
