values ('navaratri_pooja', 23, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Pushpam', 'விக்னேஸ்வர புஷ்பம்',
        'Offer a garland, then begin to worship with flowers, or with durva grass if you have it.',
        'மாலை சமர்ப்பித்து, புஷ்பங்களால், கிடைத்தால் அருகம்புல்லால், பூஜிக்கத் தொடங்கவும்.',
        'विघ्नेश्वराय नमः पुष्पमालां समर्पयामि,
पुष्पैः पूजयामि ।',
        'விக்நேஶ்வராய நம꞉ புஷ்பமாலாம் ஸமர்பயாமி,
புஷ்பை꞉ பூஜயாமி ।',
        'vighneśvarāya namaḥ puṣpamālāṃ samarpayāmi,
puṣpaiḥ pūjayāmi ।',
        'Salutations to Vighneshwara: I offer a garland of flowers; I worship with flowers.',
        'The garland is the last of the upacharas and the flowers that follow it open the archana. Durva is preferred because Ganesha is said to love the plain grass more than any bloom.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.9, step 8, puSHpamaalaam; one rubric for garland and flowers');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
