  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 2, 'ॐ एकदन्ताय नमः', 'ஓம் ஏகதந்தாய நம꞉', 'oṃ ekadantāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 3, 'ॐ कपिलाय नमः', 'ஓம் கபிலாய நம꞉', 'oṃ kapilāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 4, 'ॐ गजकर्णकाय नमः', 'ஓம் கஜகர்ணகாய நம꞉', 'oṃ gajakarṇakāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 5, 'ॐ लम्बोदराय नमः', 'ஓம் லம்போதராய நம꞉', 'oṃ lambodarāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 6, 'ॐ विकटाय नमः', 'ஓம் விகடாய நம꞉', 'oṃ vikaṭāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 7, 'ॐ विघ्नराजाय नमः', 'ஓம் விக்நராஜாய நம꞉', 'oṃ vighnarājāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 8, 'ॐ विनायकाय नमः', 'ஓம் விநாயகாய நம꞉', 'oṃ vināyakāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 9, 'ॐ धूमकेतवे नमः', 'ஓம் தூமகேதவே நம꞉', 'oṃ dhūmaketave namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 10, 'ॐ गणाध्यक्षाय नमः', 'ஓம் கணாத்யக்ஷாய நம꞉', 'oṃ gaṇādhyakṣāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 11, 'ॐ फालचन्द्राय नमः', 'ஓம் பாலசந்த்ராய நம꞉', 'oṃ phālacandrāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 12, 'ॐ गजाननाय नमः', 'ஓம் கஜாநநாய நம꞉', 'oṃ gajānanāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 13, 'ॐ वक्रतुण्डाय नमः', 'ஓம் வக்ரதுண்டாய நம꞉', 'oṃ vakratuṇḍāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 14, 'ॐ शूर्पकर्णाय नमः', 'ஓம் ஶூர்பகர்ணாய நம꞉', 'oṃ śūrpakarṇāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 15, 'ॐ हेरम्बाय नमः', 'ஓம் ஹேரம்பாய நம꞉', 'oṃ herambāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 24), 16, 'ॐ स्कन्दपूर्वजाय नमः', 'ஓம் ஸ்கந்தபூர்வஜாய நம꞉', 'oṃ skandapūrvajāya namaḥ', null, 'Offer a flower or a blade of durva', 'புஷ்பம் அல்லது அருகம்புல் சமர்ப்பிக்கவும்');

