values ('navaratri_pooja', 25, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Patra Pushpa Samarpanam', 'விக்னேஸ்வர பத்ர புஷ்ப ஸமர்ப்பணம்',
        'When the sixteen names are done, offer all the remaining leaves and flowers together.',
        'பதினாறு நாமங்கள் முடிந்ததும், மீதமுள்ள இலைகளையும் புஷ்பங்களையும் ஒன்றாகச் சமர்ப்பிக்கவும்.',
        'महागणपतये नमः नानाविध परिमल पत्र पुष्पाणि समर्पयामि ।',
        'மஹாகணபதயே நம꞉ நாநாவித பரிமல பத்ர புஷ்பாணி ஸமர்பயாமி ।',
        'mahāgaṇapataye namaḥ nānāvidha parimala patra puṣpāṇi samarpayāmi ।',
        'Salutations to Mahaganapati: I offer fragrant leaves and flowers of many kinds.',
        'The archana ends with whatever is left in the plate offered at once. Nothing gathered for the deity is kept back.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.9, step 8, the close of the archana');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 26, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Dhoopam', 'விக்னேஸ்வர தூபம்',
        'Light the incense and wave it before the turmeric Ganesha.',
        'ஊதுபத்தியை ஏற்றி மஞ்சள் பிள்ளையாரின் முன் காட்டவும்.',
        'धूपमाघ्रापयामि ।',
        'தூபமாக்ராபயாமி ।',
        'dhūpamāghrāpayāmi ।',
        'I offer incense for him to smell.',
        'Incense is offered to the sense of smell, which is why the verb is aghrapayami, "I cause to smell". Each upachara speaks to one sense of the guest.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.10, step 8, dhoopam; the printed line holds dhoopa and deepa, cut at its comma');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
