values ('navaratri_pooja', 27, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Deepam', 'விக்னேஸ்வர தீபம்',
        'Wave a lamp with a wick dipped in ghee before him.',
        'நெய்யில் நனைத்த திரியுடன் ஏற்றிய தீபத்தை அவர் முன் காட்டவும்.',
        'दीपं दर्शयामि ।',
        'தீபம் தர்ஶயாமி ।',
        'dīpaṃ darśayāmi ।',
        'I show the lamp.',
        'The lamp is shown, darshayami, not given. The guest is meant to see by it, and to be seen.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.10, step 8, deepam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
