values ('navaratri_pooja', 28, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Dhoopa Deepa Achamaniyam', 'விக்னேஸ்வர தூப தீபாநந்தர ஆசமனீயம்',
        'Pour a spoon of water into the cup.',
        'ஒரு உத்தரிணி ஜலத்தைக் கிண்ணத்தில் விடவும்.',
        'धूप दीपानन्तरं आचमनीयं समर्पयामि ।',
        'தூப தீபாநந்தரம் ஆசமநீயம் ஸமர்பயாமி ।',
        'dhūpa dīpānantaraṃ ācamanīyaṃ samarpayāmi ।',
        'After the incense and the lamp, I offer water to sip.',
        'Water closes each group of offerings. It is the rite''s punctuation, a pause between one kind of service and the next.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.10, step 8, dhoopa deepaanantaram aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 29, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Naivedya Prokshanam', 'விக்னேஸ்வர நைவேத்ய ப்ரோக்ஷணம்',
        'Clean the floor in front with a little water and set the naivedyam there on a plate or a plantain leaf; a fruit or a piece of jaggery is enough. Sprinkle water on it with the first line, then circle the plate clockwise three times with water from the uddharani as you say the Gayatri.',
        'முன்னே தரையைச் சிறிது ஜலத்தால் சுத்தம் செய்து, தட்டிலோ வாழையிலையிலோ நைவேத்யத்தை வைக்கவும்; ஒரு பழமோ சிறிது வெல்லமோ போதும். முதல் வரியுடன் அதன் மேல் ஜலம் தெளித்து, காயத்ரீ சொல்லும்போது உத்தரிணி ஜலத்தால் தட்டை மூன்று முறை வலமாகச் சுற்றவும்.',
        'ॐ भूर्भुवस्सुवः
तत्सवितुर्वरेण्यं भर्गोदेवस्य धीमहि, धियो यो नः प्रचोदयात् ।',
        'ஓம் பூர்புவஸ்ஸுவ꞉
தத்ஸவிதுர்வரேண்யம் பர்கோதேவஸ்ய தீமஹி, தியோ யோ ந꞉ ப்ரசோதயாத் ।',
        'oṃ bhūrbhuvassuvaḥ
tatsaviturvareṇyaṃ bhargodevasya dhīmahi, dhiyo yo naḥ pracodayāt ।',
        'Om, earth, sky and heaven. We meditate on the adorable radiance of the divine Savitr; may he set our minds in motion.',
        'Before Ganesha eats, the food is made fit to be offered, with the oldest words the household knows. Even a single banana is purified as a feast would be.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.11, step 8, naivEdyamantraaha: the sprinkling and the threefold circling');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 30, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Parishechanam', 'விக்னேஸ்வர பரிஷேசனம்',
        'Take water in the uddharani again and circle the plate clockwise as you say this. Say the first line in the morning and the second in the evening.',
        'மீண்டும் உத்தரிணியில் ஜலம் எடுத்து, இதைச் சொல்லியபடி தட்டை வலமாகச் சுற்றவும். காலையில் முதல் வரியையும், மாலையில் இரண்டாம் வரியையும் சொல்லவும்.',
        'देवसवितः प्रसुव । सत्यं त्वर्तेन परिषिञ्चामि।
देवसवितः प्रसुव । ऋतं त्वा सत्येन परिषिञ्चामि।',
        'தேவஸவித꞉ ப்ரஸுவ । ஸத்யம் த்வர்தேந பரிஷிஞ்சாமி।
தேவஸவித꞉ ப்ரஸுவ । ருதம் த்வா ஸத்யேந பரிஷிஞ்சாமி।',
        'devasavitaḥ prasuva । satyaṃ tvartena pariṣiñcāmi।
devasavitaḥ prasuva । ṛtaṃ tvā satyena pariṣiñcāmi।',
        'Divine Savitr, impel us. In the morning: I sprinkle you, truth, with order. In the evening: I sprinkle you, order, with truth.',
        'The two lines differ only in which word comes first, satya or rita. Morning and evening are kept apart even in a ring of water, because the rite is always placed in time.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.11, step 8, the morning and evening parishechana lines');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 31, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Amritopastaranam', 'விக்னேஸ்வர அம்ருதோபஸ்தரணம்',
        'Pour a spoon of water into the cup, as the bed for the food.',
        'உணவுக்கு அடியாக ஒரு உத்தரிணி ஜலத்தைக் கிண்ணத்தில் விடவும்.',
        'अमृतोपस्तरणमसि ।',
        'அம்ருதோபஸ்தரணமஸி ।',
        'amṛtopastaraṇamasi ।',
        'You are the immortal bed.',
        'The water poured before the food is called its bed, upastarana, and the water after it its covering. The meal is wrapped in water on both sides, as it is for anyone who eats with this rite.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.11, step 8, amRtOpastaraNamasi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 32, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Pranahuti', 'விக்னேஸ்வர ப்ராணாஹுதி',
        'At each svaha, gesture with the right hand from the food towards Ganesha, as if feeding him.',
        'ஒவ்வொரு ஸ்வாஹாவிற்கும், உணவிலிருந்து பிள்ளையாரை நோக்கி ஊட்டுவது போல் வலது கையால் காட்டவும்.',
        'ॐ प्राणाय स्वाहा, ॐ अपानाय स्वाहा, ॐ व्यानाय स्वाहा,
ॐ उदानाय स्वाहा, ॐ समानाय स्वाहा, ॐ ब्रह्मणे स्वाहा ।',
        'ஓம் ப்ராணாய ஸ்வாஹா, ஓம் அபாநாய ஸ்வாஹா, ஓம் வ்யாநாய ஸ்வாஹா,
ஓம் உதாநாய ஸ்வாஹா, ஓம் ஸமாநாய ஸ்வாஹா, ஓம் ப்ரஹ்மணே ஸ்வாஹா ।',
        'oṃ prāṇāya svāhā, oṃ apānāya svāhā, oṃ vyānāya svāhā,
oṃ udānāya svāhā, oṃ samānāya svāhā, oṃ brahmaṇe svāhā ।',
        'Om, to prana, svaha; to apana, svaha; to vyana, svaha; to udana, svaha; to samana, svaha; to Brahman, svaha.',
        'The food goes first to the five breaths and then to Brahman: the deity is fed the way a body is fed, through the breaths that take food in and turn it into life.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.11-12, step 8, the six praaNaahutis');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 33, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Amritapaniyam', 'விக்னேஸ்வர அம்ருதபானீயம்',
        'Pour a spoon of water into the cup, as water to drink with the meal.',
        'உணவின் நடுவே அருந்துவதற்காக ஒரு உத்தரிணி ஜலத்தைக் கிண்ணத்தில் விடவும்.',
        'मध्ये मध्ये अमृतपानीयं समर्पयामि ।',
        'மத்யே மத்யே அம்ருதபாநீயம் ஸமர்பயாமி ।',
        'madhye madhye amṛtapānīyaṃ samarpayāmi ।',
        'Now and again during the meal, I offer the nectar of water to drink.',
        'Madhye madhye, now and again: a good host keeps the guest''s cup filled while they eat, and the rite remembers to.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.12, step 8, madhyE madhyE amRtapaaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 34, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Amritapidhanam', 'விக்னேஸ்வர அம்ருதாபிதானம்',
        'Pour a spoon of water into the cup, to close the meal.',
        'உணவை நிறைவு செய்ய ஒரு உத்தரிணி ஜலத்தைக் கிண்ணத்தில் விடவும்.',
        'अमृतापिधानमसि । आचमनीयं समर्पयामि ।',
        'அம்ருதாபிதாநமஸி । ஆசமநீயம் ஸமர்பயாமி ।',
        'amṛtāpidhānamasi । ācamanīyaṃ samarpayāmi ।',
        'You are the immortal covering. I offer water to sip.',
        'Apidhana is a lid. The water that ends the meal is named its cover, closing what the water before it opened.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.12, step 8, amRtaapidhaanamasi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 35, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Uttaraposhanam', 'விக்னேஸ்வர உத்தராபோஶனம்',
        'Pour one more spoon of water into the cup.',
        'இன்னொரு உத்தரிணி ஜலத்தைக் கிண்ணத்தில் விடவும்.',
        'उत्तरापोशनम् समर्पयामि।',
        'உத்தராபோஶநம் ஸமர்பயாமி।',
        'uttarāpośanam samarpayāmi।',
        'I offer the last sip of water after the meal.',
        'Uttaraposhana is the sip taken at the very end of a meal. Ganesha is given the whole order of eating, nothing skipped because the meal is small.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.12, step 8, uttaraapOshanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 36, 'purvangam', '{main,punar}', 'Purvangam — Vighneshwara Pooja', 'பூர்வாங்கம் — விக்னேஸ்வர பூஜை', 'Vighneshwara Karpura Neerajanam', 'விக்னேஸ்வர கற்பூர நீராஜனம்',
        'Light camphor and wave it clockwise in front of the turmeric Ganesha.',
        'கற்பூரம் ஏற்றி, மஞ்சள் பிள்ளையாரின் முன் வலமாகச் சுற்றிக் காட்டவும்.',
        'कर्पूरनीराजनं सन्दर्शयामि।',
        'கர்பூரநீராஜநம் ஸந்தர்ஶயாமி।',
        'karpūranīrājanaṃ sandarśayāmi।',
        'I show the camphor light.',
        'The small pooja ends in camphor, as the large one will. Camphor burns away completely and leaves nothing, which is why it closes a rite.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.12, step 8, karpoora neeraajanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 37, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Pranayamam (again)', 'ப்ராணாயாமம் (மீண்டும்)',
        'Take a few grains of akshatai in the hand and do the pranayamam once more, in full: fold the index and middle fingers, breathe in through the left nostril on the first line, hold with both nostrils closed through the second, breathe out through the right on the third. Then touch the right ear with the right hand.',
        'கையில் சில அக்ஷதைகளை எடுத்துக்கொண்டு, ப்ராணாயாமத்தை மீண்டும் முழுமையாகச் செய்யவும்: ஆள்காட்டி, நடு விரல்களை மடக்கி, முதல் வரியில் இடது நாசி வழியாக மூச்சை இழுத்து, இரண்டாம் வரியில் இரு நாசிகளையும் மூடி நிறுத்தி, மூன்றாம் வரியில் வலது நாசி வழியாக வெளியிடவும். பின் வலது கையால் வலது காதைத் தொடவும்.',
        'ॐ भूः । ॐ भुवः । ओꣳ सुवः । ॐ महः । ॐ जनः । ॐ तपः । ओꣳ सत्यम् ।
ॐ तत्सवितुर्वरेण्यम् भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् ।
ओमापः ज्योतीरसः अमृतं ब्रह्म भूर्भुवस्सुवरोम् ॥',
        'ஓம் பூ꞉ । ஓம் புவ꞉ । ஓகும் ஸுவ꞉ । ஓம் மஹ꞉ । ஓம் ஜந꞉ । ஓம் தப꞉ । ஓகும் ஸத்யம் ।
ஓம் தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி । தியோ யோ ந꞉ ப்ரசோதயாத் ।
ஓமாப꞉ ஜ்யோதீரஸ꞉ அம்ருதம் ப்ரஹ்ம பூர்புவஸ்ஸுவரோம் ॥',
        'oṃ bhūḥ । oṃ bhuvaḥ । ogm suvaḥ । oṃ mahaḥ । oṃ janaḥ । oṃ tapaḥ । ogm satyam ।
oṃ tatsaviturvareṇyam bhargo devasya dhīmahi । dhiyo yo naḥ pracodayāt ।
omāpaḥ jyotīrasaḥ amṛtaṃ brahma bhūrbhuvassuvarom ॥',
        'Om, earth; Om, sky; Om, heaven; Om, the great world; Om, the world of beings; Om, the world of austerity; Om, the true. Om, we meditate on the adorable radiance of the divine Savitr; may he set our minds in motion. Om, the waters, the light, the essence, the immortal, Brahman: earth, sky and heaven, Om.',
        'The breath is steadied a second time because what comes next is the resolve for the Navaratri pooja itself. The first pranayamam readied the karta to begin; this one readies them to promise.', 'filter_male_only', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.12, step 9, praaNaayaamaha, printed in short as the full pranayama of step 3 (pp.3-4), shown here in full');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 38, 'purvangam', '{main,punar,udvasana}', 'Purvangam', 'பூர்வாங்கம்', 'Sankalpam', 'ஸங்கல்பம்',
        'Keep the akshatai in the left palm and rest it, palm up, on the right thigh, with the right palm crossed over it. Recite the day and place, and the resolve to worship Durga, Lakshmi and Saraswati. At the end, drop the akshatai to the north and wash the hand.',
        'அக்ஷதையை இடது உள்ளங்கையில் வைத்து, அதை மேல்நோக்கியபடி வலது தொடையின் மேல் வைத்து, வலது உள்ளங்கையை அதன் மேல் குறுக்காக மூடவும். நாள், இடம் இவற்றைச் சொல்லி, துர்கா லக்ஷ்மீ ஸரஸ்வதீ பூஜை செய்வதாக ஸங்கல்பம் செய்யவும். முடிவில் அக்ஷதையை வடக்குப் பக்கம் போட்டுக் கையைக் கழுவவும்.',
        'ममोपात्त समस्त-दुरित-क्षयद्वारा श्री परमेश्वर प्रीत्यर्थं शुभे शोभने मुहूर्ते,
आद्यब्रह्मणः द्वितीय परार्धे, श्वेतवराह कल्पे,
वैवस्वतमन्वन्तरे, अष्टाविंशतितमे, कलियुगे, प्रथमेपादे,
जम्बूद्वीपे, भारत वर्षे, भरतखण्डे,
मेरोः दक्षिणे पार्श्वे, शकाब्दे, अस्मिन् वर्तमाने,
व्यावहारिके प्रभवादीनां षष्ट्याः संवत्सराणां मध्ये
[DYNAMIC_PANCHANGAM_DATA]
अस्माकं सहकुटुम्बानां क्षेमस्थैर्यवीर्य-विजय-आयुरारोग्य ऐश्वर्याणां अभिवृद्ध्यर्थं,
समस्त मङ्गलावाप्त्यर्थं, समस्त दुरितोपशान्त्यर्थं,
श्री दुर्गा लक्ष्मी सरस्वती प्रसाद सिद्ध्यर्थं,
श्री दुर्गा लक्ष्मी सरस्वती पूजां करिष्ये। तदङ्गं कलश पूजां च करिष्ये।',
        'மமோபாத்த ஸமஸ்த-துரித-க்ஷயத்வாரா ஶ்ரீ பரமேஶ்வர ப்ரீத்யர்தம் ஶுபே ஶோபநே முஹூர்தே,
ஆத்யப்ரஹ்மண꞉ த்விதீய பரார்தே, ஶ்வேதவராஹ கல்பே,
வைவஸ்வதமந்வந்தரே, அஷ்டாவிம்ஶதிதமே, கலியுகே, ப்ரதமேபாதே,
ஜம்பூத்வீபே, பாரத வர்ஷே, பரதகண்டே,
மேரோ꞉ தக்ஷிணே பார்ஶ்வே, ஶகாப்தே, அஸ்மிந் வர்தமாநே,
வ்யாவஹாரிகே ப்ரபவாதீநாம் ஷஷ்ட்யா꞉ ஸம்வத்ஸராணாம் மத்யே
[DYNAMIC_PANCHANGAM_DATA]
அஸ்மாகம் ஸஹகுடும்பாநாம் க்ஷேமஸ்தைர்யவீர்ய-விஜய-ஆயுராரோக்ய ஐஶ்வர்யாணாம் அபிவ்ருத்த்யர்தம்,
ஸமஸ்த மங்கலாவாப்த்யர்தம், ஸமஸ்த துரிதோபஶாந்த்யர்தம்,
ஶ்ரீ துர்கா லக்ஷ்மீ ஸரஸ்வதீ ப்ரஸாத ஸித்த்யர்தம்,
ஶ்ரீ துர்கா லக்ஷ்மீ ஸரஸ்வதீ பூஜாம் கரிஷ்யே। ததங்கம் கலஶ பூஜாம் ச கரிஷ்யே।',
        'mamopātta samasta-durita-kṣayadvārā śrī parameśvara prītyarthaṃ śubhe śobhane muhūrte,
ādyabrahmaṇaḥ dvitīya parārdhe, śvetavarāha kalpe,
vaivasvatamanvantare, aṣṭāviṃśatitame, kaliyuge, prathamepāde,
jambūdvīpe, bhārata varṣe, bharatakhaṇḍe,
meroḥ dakṣiṇe pārśve, śakābde, asmin vartamāne,
vyāvahārike prabhavādīnāṃ ṣaṣṭyāḥ saṃvatsarāṇāṃ madhye
[DYNAMIC_PANCHANGAM_DATA]
asmākaṃ sahakuṭumbānāṃ kṣemasthairyavīrya-vijaya-āyurārogya aiśvaryāṇāṃ abhivṛddhyarthaṃ,
samasta maṅgalāvāptyarthaṃ, samasta duritopaśāntyarthaṃ,
śrī durgā lakṣmī sarasvatī prasāda siddhyarthaṃ,
śrī durgā lakṣmī sarasvatī pūjāṃ kariṣye। tadaṅgaṃ kalaśa pūjāṃ ca kariṣye।',
        'For the removal of all my wrongs and for the pleasure of the Supreme Lord: at this auspicious moment, in the second half of Brahma''s life, in the Shveta Varaha kalpa, in the age of Vaivasvata Manu, in the first quarter of the Kali age of the twenty-eighth cycle, on the continent of Jambu, in the land of Bharata, south of Meru, in the Shaka era, in this year among the sixty that begin with Prabhava, on this day so described: for the welfare, steadiness, strength, victory, long life, health and prosperity of ourselves and our household, for every auspicious thing and the quieting of every ill, and to win the grace of Sri Durga, Lakshmi and Saraswati, I shall perform the worship of Sri Durga, Lakshmi and Saraswati, and as part of it the worship of the kalasham.',
        'One resolve, three goddesses. Navaratri is often told as three nights each of Durga, Lakshmi and Saraswati, but the sankalpam names all three together every day: what is being asked for is protection, prosperity and understanding at once, because a household needs all three at once.', 'all', true, true,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.12-13 step 10, pradhaana poojaa sankalpaha (frame and purposes), with the Navaratri clause and its rubric from p.286');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 39, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Vighneshwara Udyapanam', 'விக்னேஸ்வர உத்யாபனம்',
        'Move the turmeric Ganesha a little towards the north. Take back the flowers offered to him, touch them to your eyes and place them on your head, or give them to the women of the house. Then wash the hands with a spoon of water.',
        'மஞ்சள் பிள்ளையாரைச் சிறிது வடக்குப் பக்கம் நகர்த்தவும். அவருக்குச் சமர்ப்பித்த புஷ்பங்களைப் பக்தியுடன் எடுத்து, கண்களில் ஒற்றித் தலையில் வைக்கவும், அல்லது வீட்டுப் பெண்களுக்குக் கொடுக்கவும். பின் ஒரு உத்தரிணி ஜலத்தால் கைகளைக் கழுவவும்.',
        'वक्रतुण्ड महाकाय कोटिसूर्यसमप्रभ।
निर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥
श्री विघ्नेश्वरं यथास्थानं प्रतिष्ठापयामि,
शोभनार्थे क्षेमाय पुनरागमनाय च ।
विघ्नेश्वर प्रसादं शिरसा गृह्णामि
अप उपस्पृश्य।',
        'வக்ரதுண்ட மஹாகாய கோடிஸூர்யஸமப்ரப।
நிர்விக்நம் குரு மே தேவ ஸர்வகார்யேஷு ஸர்வதா॥
ஶ்ரீ விக்நேஶ்வரம் யதாஸ்தாநம் ப்ரதிஷ்டாபயாமி,
ஶோபநார்தே க்ஷேமாய புநராகமநாய ச ।
விக்நேஶ்வர ப்ரஸாதம் ஶிரஸா க்ருஹ்ணாமி
அப உபஸ்ப்ருஶ்ய।',
        'vakratuṇḍa mahākāya koṭisūryasamaprabha।
nirvighnaṃ kuru me deva sarvakāryeṣu sarvadā॥
śrī vighneśvaraṃ yathāsthānaṃ pratiṣṭhāpayāmi,
śobhanārthe kṣemāya punarāgamanāya ca ।
vighneśvara prasādaṃ śirasā gṛhṇāmi
apa upaspṛśya।',
        'Curve-trunked, mighty-bodied, bright as a crore of suns: make all my undertakings free of obstacles, always, O God. I establish Sri Vighneshwara back in his own place, for what is good, for well-being, and so that he may come again. I receive Vighneshwara''s grace upon my head. Touching water, I wash.',
        'The small pooja is closed before the large one opens. Ganesha is thanked, moved a little north and asked to come again, so that nothing invoked is left standing when the Goddess is invited.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.14, step 11, vighnEshvara udyaapanam, with apa upaspRshya');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 40, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Kalasha Gandham', 'கலச கந்தம்',
        'Apply sandal paste to the water vessel, the panchapatram, then turmeric and kumkumam over the sandal.',
        'ஜலபாத்திரமான பஞ்சபாத்திரத்திற்குச் சந்தனம் இட்டு, அதன் மேல் மஞ்சளும் குங்குமமும் இடவும்.',
        'कलशे दिव्य परिमल गंधान् धारयामि।
गन्धस्योपरि हरिद्राकुंकुमम् समर्पयामि।',
        'கலஶே திவ்ய பரிமல கம்தாந் தாரயாமி।
கந்தஸ்யோபரி ஹரித்ராகும்குமம் ஸமர்பயாமி।',
        'kalaśe divya parimala gaṃdhān dhārayāmi।
gandhasyopari haridrākuṃkumam samarpayāmi।',
        'On the vessel I place divine, fragrant sandal; over the sandal I offer turmeric and kumkumam.',
        'The vessel that has been handing out water all morning is now itself worshipped. What serves the rite is honoured by it, and the water it holds is about to be made holy.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.14, step 12, kalasha poojaa; one rubric for sandal and vermilion');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 41, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Kalasha Tirtha Avahanam', 'கலச தீர்த்த ஆவாஹனம்',
        'Place a few tulasi leaves or flowers in the water of the vessel as you name the seven rivers.',
        'ஏழு நதிகளின் பெயர்களைச் சொல்லியபடி, பாத்திரத்தின் ஜலத்தில் சில துளசி இலைகளையோ புஷ்பங்களையோ இடவும்.',
        'ॐ गङ्गायै नमः, ॐ यमुनायै नमः, ॐ गोदावर्यै नमः,
ॐ सरस्वत्यै नमः, ॐ नर्मदायै नमः, ॐ सिन्धवे नमः
ॐ कावेर्यै नमः, सप्तकोटि महातीर्थान् आवाहयामि ।',
        'ஓம் கங்காயை நம꞉, ஓம் யமுநாயை நம꞉, ஓம் கோதாவர்யை நம꞉,
ஓம் ஸரஸ்வத்யை நம꞉, ஓம் நர்மதாயை நம꞉, ஓம் ஸிந்தவே நம꞉
ஓம் காவேர்யை நம꞉, ஸப்தகோடி மஹாதீர்தாந் ஆவாஹயாமி ।',
        'oṃ gaṅgāyai namaḥ, oṃ yamunāyai namaḥ, oṃ godāvaryai namaḥ,
oṃ sarasvatyai namaḥ, oṃ narmadāyai namaḥ, oṃ sindhave namaḥ
oṃ kāveryai namaḥ, saptakoṭi mahātīrthān āvāhayāmi ।',
        'Salutations to Ganga, to Yamuna, to Godavari, to Saraswati, to Narmada, to Sindhu, to Kaveri. I invoke the seven crore great sacred waters.',
        'Seven rivers are named over a vessel in a home. The water is not claimed to be the Ganga; the rivers are asked to come into it, which is a different kind of sentence.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.15, step 12, the seven rivers');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 42, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Kalasha Abhimantranam', 'கலச அபிமந்த்ரணம்',
        'Cover the mouth of the vessel with the right palm and recite.',
        'வலது உள்ளங்கையால் பாத்திரத்தின் வாயை மூடியபடி சொல்லவும்.',
        'कलशस्य मुखे विष्णुः कण्ठे रुद्रः समाश्रितः ।
मूले तत्र स्थितो ब्रह्मा मध्ये मातृगणाः स्मृताः ॥
कुक्षौ तु सागरास्सर्वे सप्तद्वीपा वसुन्धरा ।
ऋग्वेदोऽथ यजुर्वेदः सामवेदोऽप्यथर्वणः ॥
अङ्गैश्च सहिताः सर्वे कलशाम्बु समाश्रिताः ॥
गङ्गे च यमुने चैव गोदावरि सरस्वति।
नर्मदे सिन्धु कावेरी जलेऽस्मिन् सन्निधिं कुरु ॥
सर्वे समुद्राः सरितः तीर्थानि च नदाः ह्रदाः।
आयान्तु देवीपूजार्थं दुरितक्षयकारकाः ॥',
        'கலஶஸ்ய முகே விஷ்ணு꞉ கண்டே ருத்ர꞉ ஸமாஶ்ரித꞉ ।
மூலே தத்ர ஸ்திதோ ப்ரஹ்மா மத்யே மாத்ருகணா꞉ ஸ்ம்ருதா꞉ ॥
குக்ஷௌ து ஸாகராஸ்ஸர்வே ஸப்தத்வீபா வஸுந்தரா ।
ருக்வேதோத யஜுர்வேத꞉ ஸாமவேதோப்யதர்வண꞉ ॥
அங்கைஶ்ச ஸஹிதா꞉ ஸர்வே கலஶாம்பு ஸமாஶ்ரிதா꞉ ॥
கங்கே ச யமுநே சைவ கோதாவரி ஸரஸ்வதி।
நர்மதே ஸிந்து காவேரீ ஜலேஸ்மிந் ஸந்நிதிம் குரு ॥
ஸர்வே ஸமுத்ரா꞉ ஸரித꞉ தீர்தாநி ச நதா꞉ ஹ்ரதா꞉।
ஆயாந்து தேவீபூஜார்தம் துரிதக்ஷயகாரகா꞉ ॥',
        'kalaśasya mukhe viṣṇuḥ kaṇṭhe rudraḥ samāśritaḥ ।
mūle tatra sthito brahmā madhye mātṛgaṇāḥ smṛtāḥ ॥
kukṣau tu sāgarāssarve saptadvīpā vasundharā ।
ṛgvedo''tha yajurvedaḥ sāmavedo''pyatharvaṇaḥ ॥
aṅgaiśca sahitāḥ sarve kalaśāmbu samāśritāḥ ॥
gaṅge ca yamune caiva godāvari sarasvati।
narmade sindhu kāverī jale''smin sannidhiṃ kuru ॥
sarve samudrāḥ saritaḥ tīrthāni ca nadāḥ hradāḥ।
āyāntu devīpūjārthaṃ duritakṣayakārakāḥ ॥',
        'At the mouth of the vessel dwells Vishnu, at its neck Rudra, at its base Brahma, and in its middle the hosts of mothers. In its belly are all the oceans and the earth with its seven continents; the Rig, Yajur, Sama and Atharva Vedas with all their limbs dwell in the water of the vessel. Ganga, Yamuna, Godavari, Saraswati, Narmada, Sindhu and Kaveri: be present in this water. May all the seas, rivers, sacred fords, streams and lakes, destroyers of sin, come for the worship of the Goddess.',
        'The palm over the vessel holds in what the verse has called into it. The whole cosmos is placed inside a pot of water so that the water can then make everything else fit for worship.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.15-16, step 12, kalashasya mukhE; the feminine of the book''s dEva(dEvee) alternative');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 43, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Shankha Pooja', 'ஶங்க பூஜை',
        'If there is no conch in the house, skip this screen and the next. Set the conch on a firm stand, anoint it with sandal paste and kumkumam, and fill it with water from the panchapatram while saying the Gayatri or Om three times.',
        'வீட்டில் ஶங்கு இல்லையென்றால் இதையும் அடுத்ததையும் தவிர்க்கவும். ஶங்கை உறுதியான பீடத்தில் வைத்து, சந்தனமும் குங்குமமும் இட்டு, காயத்ரீ அல்லது ஓம் மூன்று முறை சொல்லிப் பஞ்சபாத்திரத்திலிருந்து ஜலம் நிரப்பவும்.',
        'शङ्खं चन्द्रार्क दैवत्यं मध्ये वरुण दैवतम् ।
पृष्ठे प्रजापति विद्यात् अग्रे गङ्गा सरस्वती ॥
त्वं पुरा सागरोत्पन्नः विष्णुना विधृतः करे ।
पूजितः सर्व देवैश्च पाञ्चजन्य नमोऽस्तु ते ॥
त्रैलोक्ये यानि तीर्थानि, वासुदेवस्य च आज्ञया ।
शङ्खे तिष्ठन्ति विप्रेन्द्र तस्माच्छङ्खं प्रपूजयेत् ॥
पाञ्चजन्याय विद्महे पवमानाय धीमहि ।
तन्नः शङ्खः प्रचोदयात् ॥',
        'ஶங்கம் சந்த்ரார்க தைவத்யம் மத்யே வருண தைவதம் ।
ப்ருஷ்டே ப்ரஜாபதி வித்யாத் அக்ரே கங்கா ஸரஸ்வதீ ॥
த்வம் புரா ஸாகரோத்பந்ந꞉ விஷ்ணுநா வித்ருத꞉ கரே ।
பூஜித꞉ ஸர்வ தேவைஶ்ச பாஞ்சஜந்ய நமோஸ்து தே ॥
த்ரைலோக்யே யாநி தீர்தாநி, வாஸுதேவஸ்ய ச ஆஜ்ஞயா ।
ஶங்கே திஷ்டந்தி விப்ரேந்த்ர தஸ்மாச்சங்கம் ப்ரபூஜயேத் ॥
பாஞ்சஜந்யாய வித்மஹே பவமாநாய தீமஹி ।
தந்ந꞉ ஶங்க꞉ ப்ரசோதயாத் ॥',
        'śaṅkhaṃ candrārka daivatyaṃ madhye varuṇa daivatam ।
pṛṣṭhe prajāpati vidyāt agre gaṅgā sarasvatī ॥
tvaṃ purā sāgarotpannaḥ viṣṇunā vidhṛtaḥ kare ।
pūjitaḥ sarva devaiśca pāñcajanya namo''stu te ॥
trailokye yāni tīrthāni, vāsudevasya ca ājñayā ।
śaṅkhe tiṣṭhanti viprendra tasmācchaṅkhaṃ prapūjayet ॥
pāñcajanyāya vidmahe pavamānāya dhīmahi ।
tannaḥ śaṅkhaḥ pracodayāt ॥',
        'The conch has the sun and moon for its deity, Varuna at its middle, Prajapati at its back, and Ganga and Sarasvati at its mouth. You rose long ago from the ocean and were held in Vishnu’s hand, worshipped by all the gods: salutation to you, Panchajanya. By Vasudeva’s command, every sacred water in the three worlds abides in the conch; therefore let the conch be worshipped.',
        'The conch is worshipped, not blown. Its water is what sanctifies everything else set out for the pooja, so it is treated as a vessel that holds the sacred waters of the three worlds rather than as an instrument. The step may be skipped if there is no conch in the house, which is worth reading twice: a household vidhi that expects to be performed by real households says plainly which parts require an object you may not own.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.16-17, step 13, shankha poojaa; may be skipped if there is no conch');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 44, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Shankha Archana', 'ஶங்க அர்ச்சனை',
        'If there is no conch, skip this. Offer flowers and akshatai to the conch at each name, then sprinkle its water over everything set out for the pooja and refill it from the panchapatram.',
        'ஶங்கு இல்லையென்றால் இதைத் தவிர்க்கவும். ஒவ்வொரு நாமத்திலும் ஶங்கிற்குப் புஷ்பமும் அக்ஷதையும் சமர்ப்பித்து, பின் அதன் ஜலத்தைப் பூஜைக்கு வைத்துள்ள எல்லாப் பொருட்களின் மேலும் தெளித்து, பஞ்சபாத்திரத்திலிருந்து மீண்டும் நிரப்பவும்.',
        'शङ्खाय नमः। पर्जन्याय नमः । पाञ्चजन्याय नमः ।
अं अर्कमण्डलाय नमः । रं वह्निमण्डलाय नमः ।
सं सोममण्डलाय नमः। सप्तकोटि महातीर्थेभ्यो नमः ।
शङ्खराजाय नमः । समस्तोपचारान् समर्पयामि ।',
        'ஶங்காய நம꞉। பர்ஜந்யாய நம꞉ । பாஞ்சஜந்யாய நம꞉ ।
அம் அர்கமண்டலாய நம꞉ । ரம் வஹ்நிமண்டலாய நம꞉ ।
ஸம் ஸோமமண்டலாய நம꞉। ஸப்தகோடி மஹாதீர்தேப்யோ நம꞉ ।
ஶங்கராஜாய நம꞉ । ஸமஸ்தோபசாராந் ஸமர்பயாமி ।',
        'śaṅkhāya namaḥ। parjanyāya namaḥ । pāñcajanyāya namaḥ ।
aṃ arkamaṇḍalāya namaḥ । raṃ vahnimaṇḍalāya namaḥ ।
saṃ somamaṇḍalāya namaḥ। saptakoṭi mahātīrthebhyo namaḥ ।
śaṅkharājāya namaḥ । samastopacārān samarpayāmi ।',
        'Salutations to the conch, to Parjanya, to Panchajanya; am, to the orb of the sun; ram, to the orb of fire; sam, to the orb of the moon; to the seven crore great sacred waters; to the king of conches. I offer all the upacharas.',
        'Sun, fire and moon are named with their seed syllables because the conch is held to contain all three lights. Its water then goes over everything laid out for the pooja, which is what the conch is worshipped for.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.17, step 13, the names, and the sprinkling');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 45, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Atma Pooja', 'ஆத்ம பூஜை',
        'Turn the mind inward for a few seconds, holding that the self dwelling within pervades the world and is one in essence with the supreme Self. Then place a little akshatai on your own head, as an act of worshipping yourself.',
        'சில வினாடிகள் மனதை உள்நோக்கித் திருப்பி, உள்ளே உறையும் ஆத்மா உலகெங்கும் நிறைந்தது என்றும், பரமாத்மாவுடன் ஒன்றே என்றும் நினைக்கவும். பிறகு உங்கள் தலையிலேயே சிறிது அட்சதை இட்டுக்கொள்ளவும் — அது தன்னைத் தானே பூஜிக்கும் செயல்.',
        'देहो देवालयः प्रोक्तः जीवो देवः सनातनः ।
त्यजेदज्ञान निर्माल्यं सोऽहं भावेन पूजयेत् ॥',
        'தேஹோ தேவாலய꞉ ப்ரோக்த꞉ ஜீவோ தேவ꞉ ஸநாதந꞉ ।
த்யஜேதஜ்ஞாந நிர்மால்யம் ஸோஹம் பாவேந பூஜயேத் ॥',
        'deho devālayaḥ proktaḥ jīvo devaḥ sanātanaḥ ।
tyajedajñāna nirmālyaṃ so''haṃ bhāvena pūjayet ॥',
        'The body is called a temple; the living self is the eternal deity. Cast away the withered flowers of ignorance, and worship with the thought "I am That."',
        'The one step in which the worshipper is the worshipped. You hold, for a few seconds, that the self inside you is the same as the one you are about to invoke into clay, and then you put akshatai on your own head. The verse is blunt about it: the body is the temple, the living self is the deity, and what you discard is not flowers but ignorance. Every other step points outward. This one turns around.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.18, step 14, aatma poojaa');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 46, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Peetha Pooja', 'பீட பூஜை',
        'Worship the seat on which the deity will be enshrined, offering a flower and akshatai at each name. The fourteen names build the seat upward from the power that holds everything, through the tortoise and the boar and the earth, to the jewelled pavilion, the golden pillar, the white parasol, the wish-giving tree, the ocean of milk, the two white whisks, and last the yoga seat itself.',
        'தெய்வம் எழுந்தருளப் போகும் பீடத்தைப் பூஜிக்கவும்; ஒவ்வொரு நாமத்திலும் ஒரு பூவும் அட்சதையும் சமர்ப்பிக்கவும். இந்தப் பதினான்கு நாமங்கள் அனைத்தையும் தாங்கும் ஆதாரசக்தியிலிருந்து தொடங்கி, கூர்மம், வராகம், பூமி வழியாக, ரத்ன மண்டபம், ஸ்வர்ண ஸ்தம்பம், வெண்குடை, கற்பக விருக்ஷம், க்ஷீர ஸமுத்திரம், வெண் சாமரங்கள், இறுதியாக யோக பீடாஸனம் வரை பீடத்தைக் கட்டுகின்றன.',
        'ॐ आधारशक्त्यै नमः
ॐ मूलप्रकृत्यै नमः
ॐ आदि कूर्माय नमः
ॐ आदि वराहाय नमः
ॐ अनन्ताय नमः
ॐ पृथिव्यै नमः
ॐ रत्नमण्डपाय नमः
ॐ रत्नवेदिकायै नमः
ॐ स्वर्ण स्तंभाय नमः
ॐ श्वेतच्छत्राय नमः
ॐ कल्पक वृक्षाय नमः
ॐ क्षीर समुद्राय नमः
ॐ सित चामराभ्यां नमः
ॐ योगपीठासनाय नमः',
        'ஓம் ஆதாரஶக்த்யை நம꞉
ஓம் மூலப்ரக்ருத்யை நம꞉
ஓம் ஆதி கூர்மாய நம꞉
ஓம் ஆதி வராஹாய நம꞉
ஓம் அநந்தாய நம꞉
ஓம் ப்ருதிவ்யை நம꞉
ஓம் ரத்நமண்டபாய நம꞉
ஓம் ரத்நவேதிகாயை நம꞉
ஓம் ஸ்வர்ண ஸ்தம்பாய நம꞉
ஓம் ஶ்வேதச்சத்ராய நம꞉
ஓம் கல்பக வ்ருக்ஷாய நம꞉
ஓம் க்ஷீர ஸமுத்ராய நம꞉
ஓம் ஸித சாமராப்யாம் நம꞉
ஓம் யோகபீடாஸநாய நம꞉',
        'oṃ ādhāraśaktyai namaḥ
oṃ mūlaprakṛtyai namaḥ
oṃ ādi kūrmāya namaḥ
oṃ ādi varāhāya namaḥ
oṃ anantāya namaḥ
oṃ pṛthivyai namaḥ
oṃ ratnamaṇḍapāya namaḥ
oṃ ratnavedikāyai namaḥ
oṃ svarṇa staṃbhāya namaḥ
oṃ śvetacchatrāya namaḥ
oṃ kalpaka vṛkṣāya namaḥ
oṃ kṣīra samudrāya namaḥ
oṃ sita cāmarābhyāṃ namaḥ
oṃ yogapīṭhāsanāya namaḥ',
        'Salutation to the supporting power, to primordial nature, to the first tortoise, to the first boar, to Ananta, to the earth, to the jewelled pavilion, to the jewelled altar, to the golden pillar, to the white parasol, to the wish-giving tree, to the ocean of milk, to the two white whisks, and to the seat of yoga.',
        'The seat is built before the guest arrives, and built from the bottom of the cosmos upward — the power that holds everything, primordial nature, the first tortoise, the first boar, the earth, and only then the jewelled pavilion, the golden pillar, the white parasol, the wish-giving tree. Fourteen names to furnish a spot the size of a plate. The scale is the message.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.18-19, step 15, peeTHa poojaa, fourteen names');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 47, 'purvangam', '{main,punar}', 'Purvangam', 'பூர்வாங்கம்', 'Guru Dhyanam', 'குரு த்யானம்',
        'Contemplate your own teacher, as your family tradition holds. This is the last step before the deity is meditated upon and invoked.',
        'உங்கள் குடும்ப மரபின்படி உங்கள் குருவை த்யானிக்கவும். தெய்வத்தை த்யானித்து ஆவாஹனம் செய்வதற்கு முந்தைய கடைசிப் படி இது.',
        'गुरुर्ब्रह्मा गुरुर्विष्णुः गुरुर्देवो महेश्वरः ।
गुरुस्साक्षात् परं ब्रह्म तस्मै श्री गुरवे नमः ॥',
        'குருர்ப்ரஹ்மா குருர்விஷ்ணு꞉ குருர்தேவோ மஹேஶ்வர꞉ ।
குருஸ்ஸாக்ஷாத் பரம் ப்ரஹ்ம தஸ்மை ஶ்ரீ குரவே நம꞉ ॥',
        'gururbrahmā gururviṣṇuḥ gururdevo maheśvaraḥ ।
gurussākṣāt paraṃ brahma tasmai śrī gurave namaḥ ॥',
        'The guru is Brahma, the guru is Vishnu, the guru is the god Maheshwara; the guru is verily the supreme Brahman. To that guru, salutation.',
        'The last human link before the divine one. It comes immediately before the deity is meditated on and invoked, and the placement is the argument: whatever is about to happen reaches you through someone who taught it to you, and through whoever taught them. The verse does not say the guru is like Brahma, Vishnu and Maheshwara. It says the guru is them.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.19, step 16, guru dhyaanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 48, 'pradhana', '{main}', 'Dhyanam & Avahanam', 'த்யானம் & ஆவாஹனம்', 'Dhyanam', 'த்யானம்',
        'With akshatai and flowers in the hand, close the eyes and hold the form of the Goddess in mind: the slayer of Mahisha, riding the lion. Then offer the flowers and akshatai at the kalasham or image. Say kalashe if she is in the kalasham, bimbe if in an image.',
        'கையில் அக்ஷதையும் புஷ்பமும் வைத்துக்கொண்டு, கண்களை மூடி தேவியின் வடிவத்தை மனதில் நிறுத்தவும் — மஹிஷனை வதைத்தவள், ஸிம்ஹ வாஹினி. பின் கலசத்திலோ விக்ரஹத்திலோ புஷ்பம் அக்ஷதை சமர்ப்பிக்கவும். கலசத்தில் எனில் "கலசே", விக்ரஹத்தில் எனில் "பிம்பே" என்று சொல்லவும்.',
        'महिषघ्नीं महादेवीं कुमारीं सिंहवाहिनीम्।
दानवांस्तर्जयन्तीम् च सर्वकामदुघां शिवाम्॥
ध्यायामि मनसा दुर्गां नाभिमध्ये व्यवस्थिताम्।
आगच्छ वरदे देवि दैत्यदर्पनिपातिनि॥
पूजां गृहाण सुमुखि नमस्ते शङ्करप्रिये।
सर्वतीर्थमयं वारि सर्वदेव समन्वितम्॥
इमं घटं समागच्छ तिष्ठ देवगणैस्सह।
दुर्गे देवि समागच्छ सान्निध्यं इह कल्पय॥
अस्मिन् कलशे(बिम्बे)श्रीदुर्गा लक्ष्मी सरस्वतीं ध्यायामि',
        'மஹிஷக்நீம் மஹாதேவீம் குமாரீம் ஸிம்ஹவாஹிநீம்।
தாநவாம்ஸ்தர்ஜயந்தீம் ச ஸர்வகாமதுகாம் ஶிவாம்॥
த்யாயாமி மநஸா துர்காம் நாபிமத்யே வ்யவஸ்திதாம்।
ஆகச்ச வரதே தேவி தைத்யதர்பநிபாதிநி॥
பூஜாம் க்ருஹாண ஸுமுகி நமஸ்தே ஶங்கரப்ரியே।
ஸர்வதீர்தமயம் வாரி ஸர்வதேவ ஸமந்விதம்॥
இமம் கடம் ஸமாகச்ச திஷ்ட தேவகணைஸ்ஸஹ।
துர்கே தேவி ஸமாகச்ச ஸாந்நித்யம் இஹ கல்பய॥
அஸ்மிந் கலஶே(பிம்பே)ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீம் த்யாயாமி',
        'mahiṣaghnīṃ mahādevīṃ kumārīṃ siṃhavāhinīm।
dānavāṃstarjayantīm ca sarvakāmadughāṃ śivām॥
dhyāyāmi manasā durgāṃ nābhimadhye vyavasthitām।
āgaccha varade devi daityadarpanipātini॥
pūjāṃ gṛhāṇa sumukhi namaste śaṅkarapriye।
sarvatīrthamayaṃ vāri sarvadeva samanvitam॥
imaṃ ghaṭaṃ samāgaccha tiṣṭha devagaṇaissaha।
durge devi samāgaccha sānnidhyaṃ iha kalpaya॥
asmin kalaśe(bimbe)śrīdurgā lakṣmī sarasvatīṃ dhyāyāmi',
        'Slayer of Mahisha, great Goddess, maiden riding the lion, who threatens the demons, auspicious one who yields every wish: I meditate on Durga, dwelling at the centre of my being. Come, giver of boons, who throws down the pride of demons; accept this worship, gracious one, beloved of Shankara. This water holds every sacred river and every god: come into this vessel and stay with the hosts of gods, Goddess Durga, and make yourself present here. In this kalasham (this image) I meditate on Sri Durga, Lakshmi and Saraswati.',
        'Nabhimadhye vyavasthitam, "dwelling at the centre". The Goddess is first found within and only then asked into the pot. The kalasham does not bring her; it gives the worship somewhere to face.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.286, dhyaanam (Purvanga step 17)');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 49, 'pradhana', '{main}', 'Dhyanam & Avahanam', 'த்யானம் & ஆவாஹனம்', 'Avahanam', 'ஆவாஹனம்',
        'Invite the Goddess with folded hands and offer flowers and akshatai at the kalasham or image.',
        'கைகூப்பி தேவியை எழுந்தருளச் செய்து, கலசத்திலோ விக்ரஹத்திலோ புஷ்பம் அக்ஷதை சமர்ப்பிக்கவும்.',
        'एहि दुर्गे महाभागे रक्षार्थं मम सर्वदा।
आवाहयाम्यहं देवि सर्वकामार्थ सिद्धये॥
श्रीदुर्गा लक्ष्मी सरस्वतीं आवाहयामि',
        'ஏஹி துர்கே மஹாபாகே ரக்ஷார்தம் மம ஸர்வதா।
ஆவாஹயாம்யஹம் தேவி ஸர்வகாமார்த ஸித்தயே॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீம் ஆவாஹயாமி',
        'ehi durge mahābhāge rakṣārthaṃ mama sarvadā।
āvāhayāmyahaṃ devi sarvakāmārtha siddhaye॥
śrīdurgā lakṣmī sarasvatīṃ āvāhayāmi',
        'Come, Durga, most blessed, to protect me always. I invoke you, Goddess, for the accomplishment of every aim. I invoke Sri Durga, Lakshmi and Saraswati.',
        'Raksharthm mama sarvada, "to protect me always". Durga is invited first as a protector. The other two are named after her, in the same breath, because nothing grows in a house that is not safe.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.287, aavaahanam (Purvanga step 17)');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 50, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை', 'Prana Pratishtha Viniyoga', 'ப்ராண ப்ரதிஷ்டா விநியோகம்',
        'Place the right palm on the head, the nostrils and the chest for the three lines after the first; on the right chest, the left chest and the middle of the chest for aam, hreem and krom. Join the palms for the last line.',
        'முதல் வரிக்குப் பின்வரும் மூன்று வரிகளுக்கு வலது உள்ளங்கையைத் தலை, நாசி, மார்பு மீது வைக்கவும்; ஆம், ஹ்ரீம், க்ரோம் என்பதற்கு வலது மார்பு, இடது மார்பு, மார்பின் நடு. கடைசி வரிக்குக் கைகூப்பவும்.',
        'ॐ अस्य श्री प्राणप्रतिष्ठा महामन्त्रस्य ।
ब्रह्म–विष्णु–महेश्वराः ऋषयः।
ऋग्यजुस्सामाथर्वाणि छन्दांसि ।
सकल जगत्सृष्टिस्थिति संहारकारिणी प्राणशक्तिः परादेवता ।
आं बीजम् ।
ह्रीं शक्तिः ।
क्रों कीलकम् ।
प्राण प्रतिष्ठार्थे जपे विनियोगः ।',
        'ஓம் அஸ்ய ஶ்ரீ ப்ராணப்ரதிஷ்டா மஹாமந்த்ரஸ்ய ।
ப்ரஹ்ம–விஷ்ணு–மஹேஶ்வரா꞉ ருஷய꞉।
ருக்யஜுஸ்ஸாமாதர்வாணி சந்தாம்ஸி ।
ஸகல ஜகத்ஸ்ருஷ்டிஸ்திதி ஸம்ஹாரகாரிணீ ப்ராணஶக்தி꞉ பராதேவதா ।
ஆம் பீஜம் ।
ஹ்ரீம் ஶக்தி꞉ ।
க்ரோம் கீலகம் ।
ப்ராண ப்ரதிஷ்டார்தே ஜபே விநியோக꞉ ।',
        'oṃ asya śrī prāṇapratiṣṭhā mahāmantrasya ।
brahma–viṣṇu–maheśvarāḥ ṛṣayaḥ।
ṛgyajussāmātharvāṇi chandāṃsi ।
sakala jagatsṛṣṭisthiti saṃhārakāriṇī prāṇaśaktiḥ parādevatā ।
āṃ bījam ।
hrīṃ śaktiḥ ।
kroṃ kīlakam ।
prāṇa pratiṣṭhārthe jape viniyogaḥ ।',
        'Of this great mantra for establishing life: Brahma, Vishnu and Maheshvara are the seers; the Rig, Yajur, Sama and Atharva Vedas are the metres; the supreme Goddess Prana Shakti, who creates, sustains and withdraws the whole world, is the deity. Aam is the seed, hreem the power, krom the pin. It is used in recitation to establish life.',
        'Before life is asked into the kalasham, the mantra is introduced like a person, by its seers, its metre and its deity, and each is laid on the karta''s own body. The installation begins in the one doing it.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.19-20, step 18, praaNapratiSHTHaa: rishi, chandas, devata, bija, shakti, kilaka, viniyoga, with the rubric for each');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 51, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை', 'Kara Nyasa', 'கர ந்யாஸம்',
        'Roll the index finger along the thumb from base to tip, then the thumb along the index, middle, ring and little fingers in turn, one line each. On the last line rub the palms together, front and back.',
        'கட்டைவிரலின் அடியிலிருந்து நுனி வரை ஆள்காட்டி விரலை உருட்டவும்; பின் ஆள்காட்டி, நடு, மோதிர, சுண்டு விரல்கள் ஒவ்வொன்றின் அடியிலிருந்து நுனி வரை கட்டைவிரலை உருட்டவும், ஒரு வரிக்கு ஒன்று. கடைசி வரியில் இரு உள்ளங்கைகளையும் முன்னும் பின்னும் தேய்க்கவும்.',
        'आं अंगुष्ठाभ्यां नमः ।
ह्रीं तर्जनीभ्यां नमः।
क्रों मध्यमाभ्यां नमः।
आं अनामिकाभ्यां नमः।
ह्रीं कनिष्ठिकाभ्यां नमः।
क्रों करतलकरपृष्ठाभ्यां नमः ।',
        'ஆம் அம்குஷ்டாப்யாம் நம꞉ ।
ஹ்ரீம் தர்ஜநீப்யாம் நம꞉।
க்ரோம் மத்யமாப்யாம் நம꞉।
ஆம் அநாமிகாப்யாம் நம꞉।
ஹ்ரீம் கநிஷ்டிகாப்யாம் நம꞉।
க்ரோம் கரதலகரப்ருஷ்டாப்யாம் நம꞉ ।',
        'āṃ aṃguṣṭhābhyāṃ namaḥ ।
hrīṃ tarjanībhyāṃ namaḥ।
kroṃ madhyamābhyāṃ namaḥ।
āṃ anāmikābhyāṃ namaḥ।
hrīṃ kaniṣṭhikābhyāṃ namaḥ।
kroṃ karatalakarapṛṣṭhābhyāṃ namaḥ ।',
        'Aam, to the thumbs; hreem, to the forefingers; krom, to the middle fingers; aam, to the ring fingers; hreem, to the little fingers; krom, to the palms and the backs of the hands: salutation.',
        'Kara nyasa places the syllables in the hands that will do the worship. The fingers are named one by one, so that nothing offered afterwards passes through an unprepared hand.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.20-21, step 18, kara nyaasa, with the rubric for each finger');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 52, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை', 'Anga Nyasa & Digbandha', 'அங்க ந்யாஸம் & திக்பந்தம்',
        'Touch the chest and then the forehead with the right palm, the tuft at the back of the head with the right thumb, and the shoulders with the arms crossed. Touch the left eye, the point between the brows and the right eye with the index, middle and ring fingers, and strike the left palm with the right index and middle fingers. On the last line circle the right hand clockwise around the head.',
        'வலது உள்ளங்கையால் மார்பையும் நெற்றியையும், வலது கட்டைவிரலால் பின்தலையில் குடுமியையும், கைகளைக் குறுக்காக்கி இரு தோள்களையும் தொடவும். ஆள்காட்டி, நடு, மோதிர விரல்களால் இடது கண், புருவ மத்தி, வலது கண் ஆகியவற்றைத் தொட்டு, வலது ஆள்காட்டி, நடு விரல்களால் இடது உள்ளங்கையில் தட்டவும். கடைசி வரியில் வலது கையைத் தலையைச் சுற்றி வலமாகச் சுழற்றவும்.',
        'आं हृदयाय नमः।
ह्रीं शिरसे स्वाहा।
क्रों शिखायै वषट् ।
आं कवचाय हुं ।
ह्रीं नेत्रत्रयाय वौषट् ।
क्रों अस्त्राय फट् ।
भूर्भुवस्सुवरोमिति दिग्बन्धः ।',
        'ஆம் ஹ்ருதயாய நம꞉।
ஹ்ரீம் ஶிரஸே ஸ்வாஹா।
க்ரோம் ஶிகாயை வஷட் ।
ஆம் கவசாய ஹும் ।
ஹ்ரீம் நேத்ரத்ரயாய வௌஷட் ।
க்ரோம் அஸ்த்ராய பட் ।
பூர்புவஸ்ஸுவரோமிதி திக்பந்த꞉ ।',
        'āṃ hṛdayāya namaḥ।
hrīṃ śirase svāhā।
kroṃ śikhāyai vaṣaṭ ।
āṃ kavacāya huṃ ।
hrīṃ netratrayāya vauṣaṭ ।
kroṃ astrāya phaṭ ।
bhūrbhuvassuvaromiti digbandhaḥ ।',
        'Aam, to the heart, namah; hreem, to the head, svaha; krom, to the tuft, vashat; aam, to the armour, hum; hreem, to the three eyes, vaushat; krom, to the weapon, phat. With bhur bhuvah suvar om the directions are bound.',
        'The body is sealed limb by limb, and then the directions around it are closed with one circle of the hand. Breath is asked into the image only from inside a protected space.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.21-22, step 18, anga nyaasa and digbandha, with the rubric for each line');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 53, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை', 'Prana Shakti Dhyanam', 'ப்ராணஶக்தி த்யானம்',
        'Hold in mind the supreme power of life, as the verse describes her, and recite.',
        'ஸ்லோகம் வர்ணிப்பது போல் உயிர்ச்சக்தியான பராசக்தியை மனதில் நிறுத்திச் சொல்லவும்.',
        'रक्तांबोधिस्थ–पोतोल्लसदरुण सरोजाधिरूढा कराब्जैः ।
पाशं कोदण्डमिक्षूद्भवमलिगुणमप्यंकुशं पञ्चबाणान् ॥
बिभ्राणासृक्कपालं त्रिनयनलसिताऽऽपीन वक्षोरुहाढ्या ।
देवी बालार्कवर्णा भवतु सुखकरी प्राणशक्तिः परा नः ॥',
        'ரக்தாம்போதிஸ்த–போதோல்லஸதருண ஸரோஜாதிரூடா கராப்ஜை꞉ ।
பாஶம் கோதண்டமிக்ஷூத்பவமலிகுணமப்யம்குஶம் பஞ்சபாணாந் ॥
பிப்ராணாஸ்ருக்கபாலம் த்ரிநயநலஸிதாபீந வக்ஷோருஹாட்யா ।
தேவீ பாலார்கவர்ணா பவது ஸுககரீ ப்ராணஶக்தி꞉ பரா ந꞉ ॥',
        'raktāṃbodhistha–potollasadaruṇa sarojādhirūḍhā karābjaiḥ ।
pāśaṃ kodaṇḍamikṣūdbhavamaliguṇamapyaṃkuśaṃ pañcabāṇān ॥
bibhrāṇāsṛkkapālaṃ trinayanalasitā''''pīna vakṣoruhāḍhyā ।
devī bālārkavarṇā bhavatu sukhakarī prāṇaśaktiḥ parā naḥ ॥',
        'May the supreme Prana Shakti be the giver of happiness to us: the Goddess the colour of the rising sun, mounted on a red lotus on a shining boat in a sea of red, holding in her lotus hands the noose, the bow of sugarcane with its string of bees, the goad, the five arrows and a skull of blood, three-eyed and full-breasted.',
        'The power about to be asked into the kalasham is itself a goddess, and she is seen before she is called. In a Navaratri pooja the life breathed into the Goddess''s seat is a Goddess too.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.23, step 18, dhyaanam of the Prana Shakti');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 54, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை',
        'Keep the mind on the kalasham or image and recite, asking breath, life and every sense to come and stay in it.',
        'மனதைக் கலசத்தின் மேலோ விக்ரஹத்தின் மேலோ நிறுத்தி, உயிர்ப்பும் ஜீவனும் எல்லா இந்திரியங்களும் அதில் வந்து நிலைக்கும்படி வேண்டிச் சொல்லவும்.',
        'ॐ आं ह्रीं क्रों ।
क्रों ह्रीं आं ।
अं यं रं लं वं शं षं सं हं ।
हंसः सोऽहं, सोऽहं हंसः ।
अस्यां मूर्तौ प्राणस्तिष्ठतु जीवस्तिष्ठतु अस्यां मूर्तौ सर्वेन्द्रियाणि
वाङ्–मनस्–त्वक्–चक्षुः–श्रोत्र–जिह्वा–घ्राण–पाणि–पाद
पायूपस्थानि, प्राणापान व्यानोदान–समानाः इहागत्य स्वस्ति
सुखं चिरं तिष्ठन्तु स्वाहा ॥ सान्निध्यं कुरु स्वाहा।',
        'ஓம் ஆம் ஹ்ரீம் க்ரோம் ।
க்ரோம் ஹ்ரீம் ஆம் ।
அம் யம் ரம் லம் வம் ஶம் ஷம் ஸம் ஹம் ।
ஹம்ஸ꞉ ஸோஹம், ஸோஹம் ஹம்ஸ꞉ ।
அஸ்யாம் மூர்தௌ ப்ராணஸ்திஷ்டது ஜீவஸ்திஷ்டது அஸ்யாம் மூர்தௌ ஸர்வேந்த்ரியாணி
வாங்–மநஸ்–த்வக்–சக்ஷு꞉–ஶ்ரோத்ர–ஜிஹ்வா–க்ராண–பாணி–பாத
பாயூபஸ்தாநி, ப்ராணாபாந வ்யாநோதாந–ஸமாநா꞉ இஹாகத்ய ஸ்வஸ்தி
ஸுகம் சிரம் திஷ்டந்து ஸ்வாஹா ॥ ஸாந்நித்யம் குரு ஸ்வாஹா।',
        'oṃ āṃ hrīṃ kroṃ ।
kroṃ hrīṃ āṃ ।
aṃ yaṃ raṃ laṃ vaṃ śaṃ ṣaṃ saṃ haṃ ।
haṃsaḥ so''haṃ, so''haṃ haṃsaḥ ।
asyāṃ mūrtau prāṇastiṣṭhatu jīvastiṣṭhatu asyāṃ mūrtau sarvendriyāṇi
vāṅ–manas–tvak–cakṣuḥ–śrotra–jihvā–ghrāṇa–pāṇi–pāda
pāyūpasthāni, prāṇāpāna vyānodāna–samānāḥ ihāgatya svasti
sukhaṃ ciraṃ tiṣṭhantu svāhā ॥ sānnidhyaṃ kuru svāhā।',
        'Om aam hreem krom, krom hreem aam; am, yam, ram, lam, vam, sham, sham, sam, ham; hamsah so''ham, so''ham hamsah. In this form let the breath stay and the life stay; in this form let all the senses, speech, mind, skin, eye, ear, tongue, smell, hands, feet and the lower organs, and the five breaths, come here and remain long in well-being and happiness, svaha. Be present here, svaha.',
        'Hamsah so''ham, "I am that", is the sound of the breath read both ways. The life asked into the image is not fetched from elsewhere; it is the same life that breathes in the one asking.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.23-24, step 18, the bija and the praaNastiSHTHatu');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 55, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை', 'Asunite Mantra', 'அஸுநீதே மந்த்ரம்',
        'First say Om fifteen times, for the fifteen sacraments of the deity from birth onwards. Then recite the verse.',
        'முதலில், ஜாதகர்மம் முதலான பதினைந்து ஸம்ஸ்காரங்களுக்காக "ஓம்" பதினைந்து முறை சொல்லவும். பின் இந்த மந்த்ரத்தைச் சொல்லவும்.',
        'असुनीते पुनरस्मासु चक्षुः पुनः प्राणमिह नो धेहि भोगम् ।
ज्योक् पश्येम सूर्यमुच्चरन्तमनुमते मृलया नः स्वस्ति ॥
प्राणान् प्रतिष्ठापयामि ।',
        'அஸுநீதே புநரஸ்மாஸு சக்ஷு꞉ புந꞉ ப்ராணமிஹ நோ தேஹி போகம் ।
ஜ்யோக் பஶ்யேம ஸூர்யமுச்சரந்தமநுமதே ம்ருலயா ந꞉ ஸ்வஸ்தி ॥
ப்ராணாந் ப்ரதிஷ்டாபயாமி ।',
        'asunīte punarasmāsu cakṣuḥ punaḥ prāṇamiha no dhehi bhogam ।
jyok paśyema sūryamuccarantamanumate mṛlayā naḥ svasti ॥
prāṇān pratiṣṭhāpayāmi ।',
        'Asuniti, giver of breath: give us back sight, and breath, and the enjoyment of life here, so that we may long see the sun rising; Anumati, be gracious and keep us well. I establish the breaths.',
        'The fifteen Oms give the image, in a few seconds, every rite of passage a life receives from birth. The Vedic verse then asks for sight and breath for us, not for the image: life is invoked by people asking to stay alive.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.24, step 18, asuneetE, with the rubric to chant Om fifteen times first');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 56, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை', 'Avahita Bhava', 'ஆவாஹிதா பவ',
        'Recite each line to the Goddess in its feminine form. At the end, say kalashe''smin if she is in the kalasham, or pratimayam if in an image.',
        'ஒவ்வொரு வரியையும் அதன் ஸ்த்ரீலிங்க ரூபத்தில் தேவியை நோக்கிச் சொல்லவும். முடிவில், கலசத்தில் எனில் "கலசே(அ)ஸ்மின்", விக்ரஹத்தில் எனில் "ப்ரதிமாயாம்" என்று சொல்லவும்.',
        'आवाहिता भव ।
स्थापिता भव ।
सन्निहिता भव ।
सन्निरुद्धा भव ।
अवकुण्ठिता भव ।
सुप्रीता भव ।
सुप्रसन्ना भव ।
सुमुखी भव ।
वरदा भव ।
देवि सर्वजगन्नायिके
यावत्पूजावसानकाले तावत् त्वं प्रीतिभावेन बिंबेऽस्मिन्
(कलशेऽस्मिन् /प्रतिमायां) सन्निधिं कुरु ॥',
        'ஆவாஹிதா பவ ।
ஸ்தாபிதா பவ ।
ஸந்நிஹிதா பவ ।
ஸந்நிருத்தா பவ ।
அவகுண்டிதா பவ ।
ஸுப்ரீதா பவ ।
ஸுப்ரஸந்நா பவ ।
ஸுமுகீ பவ ।
வரதா பவ ।
தேவி ஸர்வஜகந்நாயிகே
யாவத்பூஜாவஸாநகாலே தாவத் த்வம் ப்ரீதிபாவேந பிம்பேஸ்மிந்
(கலஶேஸ்மிந் /ப்ரதிமாயாம்) ஸந்நிதிம் குரு ॥',
        'āvāhitā bhava ।
sthāpitā bhava ।
sannihitā bhava ।
sanniruddhā bhava ।
avakuṇṭhitā bhava ।
suprītā bhava ।
suprasannā bhava ।
sumukhī bhava ।
varadā bhava ।
devi sarvajagannāyike
yāvatpūjāvasānakāle tāvat tvaṃ prītibhāvena biṃbe''smin
(kalaśe''smin /pratimāyāṃ) sannidhiṃ kuru ॥',
        'Be invoked, be installed, be near, be held here, be veiled, be well pleased, be gracious, be fair of face, be the giver of boons. Goddess, mistress of all the world: until the pooja ends, stay with love in this image (in this kalasham, in this form).',
        'The endings are feminine because the guest is the Goddess; only the words change with the deity, not the welcome. She is asked to stay until the pooja ends, which over Navaratri means until Vijayadashami.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga pp.24-25, step 18, the dEvee column (the feminine forms), and dEvi sarvajagannaayikE');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 57, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை', 'Ksheera Naivedyam', 'க்ஷீர நைவேத்யம்',
        'Offer a little milk to the Goddess as the first food, reciting the Gayatri over it.',
        'காயத்ரீ சொல்லி, முதல் உணவாகச் சிறிது பாலைத் தேவிக்கு நிவேதனம் செய்யவும்.',
        'ॐ भूर्भुवस्सुवः तत्सवितुर्वरेण्यम् भर्गो देवस्य धीमहि ।
धियो यो नः प्रचोदयात्
प्राणप्रतिष्ठापनकाले क्षीरं निवेदयामि।',
        'ஓம் பூர்புவஸ்ஸுவ꞉ தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி ।
தியோ யோ ந꞉ ப்ரசோதயாத்
ப்ராணப்ரதிஷ்டாபநகாலே க்ஷீரம் நிவேதயாமி।',
        'oṃ bhūrbhuvassuvaḥ tatsaviturvareṇyam bhargo devasya dhīmahi ।
dhiyo yo naḥ pracodayāt
prāṇapratiṣṭhāpanakāle kṣīraṃ nivedayāmi।',
        'Om, earth, sky and heaven; we meditate on the adorable radiance of the divine Savitr; may he set our minds in motion. At the time of establishing life, I offer milk.',
        'The first thing given to a newly installed presence is milk, as it is to a newborn. The rite follows the life it has just invoked from its very first moment.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Purvanga p.26, after praaNapratiSHTHaa, kSHeeram nivEdayaami');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 58, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Asanam', 'ஆஸனம்',
        'Offer flowers and akshatai at the kalasham or image, as the Goddess''s seat.',
        'தேவிக்கு ஆஸனமாகக் கலசத்திலோ விக்ரஹத்திலோ புஷ்பமும் அக்ஷதையும் சமர்ப்பிக்கவும்.',
        'अनेकरत्न संयुक्तं नानामणिगणान्वितम्।
कार्तस्वरमयं दिव्यमासनं प्रतिगृह्यताम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आसनं समर्पयामि',
        'அநேகரத்ந ஸம்யுக்தம் நாநாமணிகணாந்விதம்।
கார்தஸ்வரமயம் திவ்யமாஸநம் ப்ரதிக்ருஹ்யதாம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆஸநம் ஸமர்பயாமி',
        'anekaratna saṃyuktaṃ nānāmaṇigaṇānvitam।
kārtasvaramayaṃ divyamāsanaṃ pratigṛhyatām॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ āsanaṃ samarpayāmi',
        'Receive this divine golden seat, set with many jewels and clusters of gems. Salutations to Sri Durga, Lakshmi and Saraswati: I offer a seat.',
        'Kartasvaramayam, "made of gold". The seat is described as the finest the speaker can imagine, and a handful of flowers carries the description.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.288, aasanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 59, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Padyam', 'பாத்யம்',
        'Offer an uddharani of water into the plate, for her feet.',
        'அவள் பாதங்களுக்காக ஒரு உத்தரிணி ஜலத்தைத் தாம்பாளத்தில் விடவும்.',
        'गङ्गादि सर्व तीर्थेभ्यो मया प्रार्थनयाहृतम्।
तोयमेतत् सुखस्पर्शं पाद्यार्थं प्रतिगृह्यताम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः पाद्यं समर्पयामि',
        'கங்காதி ஸர்வ தீர்தேப்யோ மயா ப்ரார்தநயாஹ்ருதம்।
தோயமேதத் ஸுகஸ்பர்ஶம் பாத்யார்தம் ப்ரதிக்ருஹ்யதாம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ பாத்யம் ஸமர்பயாமி',
        'gaṅgādi sarva tīrthebhyo mayā prārthanayāhṛtam।
toyametat sukhasparśaṃ pādyārthaṃ pratigṛhyatām॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ pādyaṃ samarpayāmi',
        'Water brought at my request from the Ganga and every sacred river, pleasant to the touch: receive it for your feet. Salutations to Sri Durga, Lakshmi and Saraswati: I offer water for the feet.',
        'Gangadi sarva tirthebhyah: the water for her feet is asked to be every holy river at once. The humblest service to her is offered at the highest grade.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.288, paadyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 60, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Arghyam', 'அர்க்யம்',
        'Offer an uddharani of water with akshatai, sandal and a flower in it.',
        'அக்ஷதை, சந்தனம், புஷ்பம் கலந்த ஒரு உத்தரிணி ஜலத்தைச் சமர்ப்பிக்கவும்.',
        'निधीनां सर्वरत्नानां त्वं अनर्घ्यगुणाह्यसि।
सिंहोपरिस्थिते देवि गृहाणार्घ्यं नमोऽस्तु ते॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः अर्घ्यं समर्पयामि',
        'நிதீநாம் ஸர்வரத்நாநாம் த்வம் அநர்க்யகுணாஹ்யஸி।
ஸிம்ஹோபரிஸ்திதே தேவி க்ருஹாணார்க்யம் நமோஸ்து தே॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ அர்க்யம் ஸமர்பயாமி',
        'nidhīnāṃ sarvaratnānāṃ tvaṃ anarghyaguṇāhyasi।
siṃhoparisthite devi gṛhāṇārghyaṃ namo''stu te॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ arghyaṃ samarpayāmi',
        'Among all treasures and jewels you are beyond price; Goddess seated on the lion, receive this arghyam: salutations to you. Salutations to Sri Durga, Lakshmi and Saraswati: I offer arghyam.',
        'Simhoparisthite, "seated on the lion". Even the water of welcome is offered to the Goddess on her mount, never to an abstract presence.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.288, arghyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 61, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Achamaniyam', 'ஆசமனீயம்',
        'Offer an uddharani of scented water for her to sip.',
        'அவள் அருந்துவதற்காக ஒரு உத்தரிணி வாசனை ஜலம் சமர்ப்பிக்கவும்.',
        'कर्पूरेण सुगन्धेन सुरभि स्वादु शीतलम्।
तोयमाचमनीयार्थं देवि त्वं प्रतिगृह्यताम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आचमनीयं समर्पयामि',
        'கர்பூரேண ஸுகந்தேந ஸுரபி ஸ்வாது ஶீதலம்।
தோயமாசமநீயார்தம் தேவி த்வம் ப்ரதிக்ருஹ்யதாம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆசமநீயம் ஸமர்பயாமி',
        'karpūreṇa sugandhena surabhi svādu śītalam।
toyamācamanīyārthaṃ devi tvaṃ pratigṛhyatām॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ ācamanīyaṃ samarpayāmi',
        'Cool, sweet, fragrant water, scented with camphor: receive it to sip, Goddess. Salutations to Sri Durga, Lakshmi and Saraswati: I offer water to sip.',
        'Camphor in the water for sipping is a refinement, not a necessity. The verse dwells on coolness and fragrance because a guest is given water at its best.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja pp.288-289, aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 62, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Snanam', 'ஸ்நானம்',
        'Sprinkle water over the kalasham or image with a flower.',
        'புஷ்பத்தால் கலசத்தின் மேலோ விக்ரஹத்தின் மேலோ ஜலம் தெளிக்கவும்.',
        'मन्दाकिन्याः समानीतैर्हेमाम्भोरुहवासितैः।
स्नानं कुरुष्व देवेशि सलिलैश्च सुगन्धिभिः॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः स्नानं समर्पयामि',
        'மந்தாகிந்யா꞉ ஸமாநீதைர்ஹேமாம்போருஹவாஸிதை꞉।
ஸ்நாநம் குருஷ்வ தேவேஶி ஸலிலைஶ்ச ஸுகந்திபி꞉॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஸ்நாநம் ஸமர்பயாமி',
        'mandākinyāḥ samānītairhemāmbhoruhavāsitaiḥ।
snānaṃ kuruṣva deveśi salilaiśca sugandhibhiḥ॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ snānaṃ samarpayāmi',
        'Bathe, Queen of the gods, in fragrant water brought from the Mandakini and scented with golden lotuses. Salutations to Sri Durga, Lakshmi and Saraswati: I offer a bath.',
        'Mandakini is the Ganga as it flows in heaven. The water in the uddharani is whatever the tap gave this morning; the verse says what it is being treated as, and the treating is the rite.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.289, snaanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 63, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Vastram', 'வஸ்த்ரம்',
        'Offer new clothes: a pair of cloths with a blouse piece, or a cloth draped on the kalasham.',
        'புதிய வஸ்திரம் சமர்ப்பிக்கவும்: ரவிக்கைத் துணியுடன் இரண்டு துணிகள், அல்லது கலசத்திற்குச் சாற்றும் ஒரு துணி.',
        'पट्टकूलयुगं देवि कञ्चुकेन समन्वितम्।
परिधेहि कृपां कृत्वा दुर्गे दुर्गतिनाशिनि॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः वस्त्रयुग्मं समर्पयामि',
        'பட்டகூலயுகம் தேவி கஞ்சுகேந ஸமந்விதம்।
பரிதேஹி க்ருபாம் க்ருத்வா துர்கே துர்கதிநாஶிநி॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ வஸ்த்ரயுக்மம் ஸமர்பயாமி',
        'paṭṭakūlayugaṃ devi kañcukena samanvitam।
paridhehi kṛpāṃ kṛtvā durge durgatināśini॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ vastrayugmaṃ samarpayāmi',
        'A pair of silk cloths with a bodice: put them on, Goddess, out of kindness, Durga who destroys misfortune. Salutations to Sri Durga, Lakshmi and Saraswati: I offer a pair of garments.',
        'Durgatinashini, "destroyer of misfortune", is a play on her name: Durga is the one who carries you across what is durga, hard to cross. The epithet turns up at the moment she is being dressed, as a guest is, for the days she is staying.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.289, vastrayugmam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 64, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Upaveetam', 'உபவீதம்',
        'Offer the sacred thread.',
        'உபவீதம் சமர்ப்பிக்கவும்.',
        'स्वर्णसूत्रमयं दिव्यं ब्रह्मणा निर्मितं पुरा।
उपवीतं मया दत्तं गृहाण परमेश्वरि॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः उपवीतं समर्पयामि',
        'ஸ்வர்ணஸூத்ரமயம் திவ்யம் ப்ரஹ்மணா நிர்மிதம் புரா।
உபவீதம் மயா தத்தம் க்ருஹாண பரமேஶ்வரி॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ உபவீதம் ஸமர்பயாமி',
        'svarṇasūtramayaṃ divyaṃ brahmaṇā nirmitaṃ purā।
upavītaṃ mayā dattaṃ gṛhāṇa parameśvari॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ upavītaṃ samarpayāmi',
        'This divine thread of golden strands, made by Brahma long ago: accept the sacred thread I give, Supreme Goddess. Salutations to Sri Durga, Lakshmi and Saraswati: I offer the sacred thread.',
        'The verse calls the thread Brahma''s own making. Offered to the Goddess it is a gift of the order of the world, given to her who sustains it.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja pp.289-290, upaveetam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 65, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Gandham', 'கந்தம்',
        'Offer sandal paste.',
        'சந்தனம் சமர்ப்பிக்கவும்.',
        'श्रीखण्डचन्दनं दिव्यं गन्धाढ्यं सुमनोहरम्।
विलेपनं च देवेशि चन्दनं प्रतिगृह्यताम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः गन्धान् धारयामि',
        'ஶ்ரீகண்டசந்தநம் திவ்யம் கந்தாட்யம் ஸுமநோஹரம்।
விலேபநம் ச தேவேஶி சந்தநம் ப்ரதிக்ருஹ்யதாம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கந்தாந் தாரயாமி',
        'śrīkhaṇḍacandanaṃ divyaṃ gandhāḍhyaṃ sumanoharam।
vilepanaṃ ca deveśi candanaṃ pratigṛhyatām॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ gandhān dhārayāmi',
        'Divine sandal paste of the sandal tree, rich in fragrance and lovely: receive it as an ointment, Queen of the gods. Salutations to Sri Durga, Lakshmi and Saraswati: I apply sandal paste.',
        'Sandal cools. It comes first among the adornments because it soothes, before anything is added for beauty.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.290, gandham');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 66, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Manjal (Saubhagya Dravyam)', 'மஞ்சள் (ஸௌபாக்ய த்ரவ்யம்)',
        'Offer turmeric.',
        'மஞ்சள் சமர்ப்பிக்கவும்.',
        'श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः सौभाग्यद्रव्याणि समर्पयामि',
        'ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஸௌபாக்யத்ரவ்யாணி ஸமர்பயாமி',
        'śrīdurgā lakṣmī sarasvatī devyai namaḥ saubhāgyadravyāṇi samarpayāmi',
        'Salutations to Sri Durga, Lakshmi and Saraswati: I offer the articles of good fortune.',
        'Turmeric, kumkumam and kajal are saubhagya dravyas, the marks of a woman whose household is whole. They are offered to the Goddess for the same reason the sumangalis who visit during these nine days are given them on the way out.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.290, saubhaagyadravyaaNi, rubric: offer turmeric paste');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 67, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Kumkumam', 'குங்குமம்',
        'Offer kumkumam.',
        'குங்குமம் சமர்ப்பிக்கவும்.',
        'श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कुङ्कुमं समर्पयामि',
        'ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ குங்குமம் ஸமர்பயாமி',
        'śrīdurgā lakṣmī sarasvatī devyai namaḥ kuṅkumaṃ samarpayāmi',
        'Salutations to Sri Durga, Lakshmi and Saraswati: I offer kumkumam.',
        'Kumkumam is the red of auspiciousness worn on the forehead and in the parting of the hair. It is offered to her as the sign of a household that is whole.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.290, kunkumam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 68, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Kanmai (Kajjalam)', 'கண்மை (கஜ்ஜலம்)',
        'Offer kanmai, the kajal for the eyes.',
        'கண்மை சமர்ப்பிக்கவும்.',
        'श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कज्जलं समर्पयामि',
        'ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கஜ்ஜலம் ஸமர்பயாமி',
        'śrīdurgā lakṣmī sarasvatī devyai namaḥ kajjalaṃ samarpayāmi',
        'Salutations to Sri Durga, Lakshmi and Saraswati: I offer kajal.',
        'Kajal is the most intimate of the adornments, put on the eyes. The Goddess is dressed as a daughter of the house is dressed for a festival, down to her eyes.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.290, kajjalam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 69, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Abharanam', 'ஆபரணம்',
        'Offer ornaments: a bangle, a chain, whatever the house sets aside for her.',
        'ஆபரணங்கள் சமர்ப்பிக்கவும் — வளையல், சங்கிலி, அவளுக்கென்று வைத்திருப்பது எதுவோ அது.',
        'श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आभरणानि समर्पयामि',
        'ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆபரணாநி ஸமர்பயாமி',
        'śrīdurgā lakṣmī sarasvatī devyai namaḥ ābharaṇāni samarpayāmi',
        'Salutations to Sri Durga, Lakshmi and Saraswati: I offer ornaments.',
        'Abharanani is plural. Vighneshwara was offered an ornament; the Goddess is offered ornaments, as befits a guest who stays for nine nights.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.290, aabharaNaani');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 70, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Akshatai', 'அக்ஷதை',
        'Offer akshatai.',
        'அக்ஷதை சமர்ப்பிக்கவும்.',
        'अक्षतान् निर्मलान् शुद्धान् मुक्तामणिसमन्वितान्।
गृहाणेमान् महादेवि देहि मे निर्मलां धियम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः अक्षतान् समर्पयामि',
        'அக்ஷதாந் நிர்மலாந் ஶுத்தாந் முக்தாமணிஸமந்விதாந்।
க்ருஹாணேமாந் மஹாதேவி தேஹி மே நிர்மலாம் தியம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ அக்ஷதாந் ஸமர்பயாமி',
        'akṣatān nirmalān śuddhān muktāmaṇisamanvitān।
gṛhāṇemān mahādevi dehi me nirmalāṃ dhiyam॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ akṣatān samarpayāmi',
        'Unbroken grains, spotless and pure, set with pearls and gems: receive them, great Goddess, and give me a spotless mind. Salutations to Sri Durga, Lakshmi and Saraswati: I offer unbroken rice.',
        'Dehi me nirmalam dhiyam, "give me a spotless mind". The one request tucked into the upacharas is not for wealth or safety but for clear thinking, which is Saraswati being asked for in the middle of a Durga verse.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.291, akSHataan');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 71, 'pradhana', '{main,punar}', 'Shodashopachara', 'ஷோடசோபசாரம்', 'Pushpam', 'புஷ்பம்',
        'Offer a garland, then loose flowers.',
        'மாலை சமர்ப்பித்து, பின் உதிரிப் புஷ்பங்களைச் சமர்ப்பிக்கவும்.',
        'पद्मशङ्खज पुष्पादि शतपत्रैर्विचित्रिताम्।
पुष्पमालां प्रयच्छामि गृहाण त्वं सुरेश्वरि॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः
पुष्पमालां समर्पयामि। पुष्पैः पूजयामि।',
        'பத்மஶங்கஜ புஷ்பாதி ஶதபத்ரைர்விசித்ரிதாம்।
புஷ்பமாலாம் ப்ரயச்சாமி க்ருஹாண த்வம் ஸுரேஶ்வரி॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉
புஷ்பமாலாம் ஸமர்பயாமி। புஷ்பை꞉ பூஜயாமி।',
        'padmaśaṅkhaja puṣpādi śatapatrairvicitritām।
puṣpamālāṃ prayacchāmi gṛhāṇa tvaṃ sureśvari॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ
puṣpamālāṃ samarpayāmi। puṣpaiḥ pūjayāmi।',
        'A garland made with lotus flowers and others of a hundred petals: I offer it; receive it, Queen of the gods. Salutations to Sri Durga, Lakshmi and Saraswati: I offer a garland of flowers; I worship with flowers.',
        'Shatapatra, "of a hundred petals". The garland closes the upacharas, and the loose flowers that follow lead straight into the names, where every flower carries one.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.291, puSHpamaalaam; one rubric for garland and flowers');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 72, 'pradhana', '{main,punar}', 'Archana', 'அர்ச்சனை', 'Anga Pooja', 'அங்க பூஜை',
        'Eighteen names, each with a limb, from the feet up to the head and then the whole body. Offer a flower or a pinch of akshatai at each.',
        'பதினெட்டு நாமங்கள், ஒவ்வொன்றும் ஒரு அங்கத்துடன், பாதம் முதல் சிரசு வரை, கடைசியில் முழு உடல். ஒவ்வொன்றிலும் ஒரு புஷ்பமோ சிறிது அக்ஷதையோ சமர்ப்பிக்கவும்.',
        null,
        null,
        null,
        'Eighteen names of the Goddess, each offered to a limb from the feet upward: Durga at the feet, Mahakali at the ankles, Kamalavasini at the navel, Maheshvari at the head, and Katyayani for the whole body.',
        'The names move between her fierce and gentle forms as they climb, Kali at the ankles and Kamalavasini, the lotus-dweller, at the navel. The anga pooja does not pick one aspect of the Goddess; it covers her from foot to head with all of them.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja pp.291-292, angapoojaa');

insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit,
   offering_deva, offering_en, offering_ta)
values
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 1, 'ॐ दुर्गायै नमः', 'ஓம் துர்காயை நம꞉', 'oṃ durgāyai namaḥ', 'पादौ पूजयामि', 'Worship the feet', 'பாதௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 2, 'ॐ महाकाल्यै नमः', 'ஓம் மஹாகால்யை நம꞉', 'oṃ mahākālyai namaḥ', 'गुल्फौ पूजयामि', 'Worship the ankle', 'குல்பௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 3, 'ॐ मंगलायै नमः', 'ஓம் மம்கலாயை நம꞉', 'oṃ maṃgalāyai namaḥ', 'जानुनी पूजयामि', 'Worship the knee', 'ஜாநுநீ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 4, 'ॐ कात्यायन्यै नमः', 'ஓம் காத்யாயந்யை நம꞉', 'oṃ kātyāyanyai namaḥ', 'ऊरू पूजयामि', 'Worship the thigh', 'ஊரூ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 5, 'ॐ भद्रकाल्यै नमः', 'ஓம் பத்ரகால்யை நம꞉', 'oṃ bhadrakālyai namaḥ', 'कटिं पूजयामि', 'Worship the waist', 'கடிம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 6, 'ॐ कमलवासिन्यै नमः', 'ஓம் கமலவாஸிந்யை நம꞉', 'oṃ kamalavāsinyai namaḥ', 'नाभिं पूजयामि', 'Worship the navel', 'நாபிம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 7, 'ॐ शिवायै नमः', 'ஓம் ஶிவாயை நம꞉', 'oṃ śivāyai namaḥ', 'उदरं पूजयामि', 'Worship the stomach', 'உதரம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 8, 'ॐ क्षमायै नमः', 'ஓம் க்ஷமாயை நம꞉', 'oṃ kṣamāyai namaḥ', 'हृदयं पूजयामि', 'Worship the heart', 'ஹ்ருதயம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 9, 'ॐ कौमार्यै नमः', 'ஓம் கௌமார்யை நம꞉', 'oṃ kaumāryai namaḥ', 'स्तनौ पूजयामि', 'Worship the breasts', 'ஸ்தநௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 10, 'ॐ उमायै नमः', 'ஓம் உமாயை நம꞉', 'oṃ umāyai namaḥ', 'हस्तौ पूजयामि', 'Worship the hands', 'ஹஸ்தௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 11, 'ॐ महागौर्यै नमः', 'ஓம் மஹாகௌர்யை நம꞉', 'oṃ mahāgauryai namaḥ', 'दक्षिणबाहुं पूजयामि', 'Worship the right arm', 'தக்ஷிணபாஹும் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 12, 'ॐ वैष्णव्यै नमः', 'ஓம் வைஷ்ணவ்யை நம꞉', 'oṃ vaiṣṇavyai namaḥ', 'वामबाहुं पूजयामि', 'Worship the left arm', 'வாமபாஹும் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 13, 'ॐ रमायै नमः', 'ஓம் ரமாயை நம꞉', 'oṃ ramāyai namaḥ', 'स्कन्धौ पूजयामि', 'Worship the shoulders', 'ஸ்கந்தௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 14, 'ॐ स्कन्दमात्रे नमः', 'ஓம் ஸ்கந்தமாத்ரே நம꞉', 'oṃ skandamātre namaḥ', 'कण्ठं पूजयामि', 'Worship the neck', 'கண்டம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 15, 'ॐ महिषमर्दिन्यै नमः', 'ஓம் மஹிஷமர்திந்யை நம꞉', 'oṃ mahiṣamardinyai namaḥ', 'नेत्रे पूजयामि', 'Worship the eyes', 'நேத்ரே பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 16, 'ॐ सिंहवाहिन्यै नमः', 'ஓம் ஸிம்ஹவாஹிந்யை நம꞉', 'oṃ siṃhavāhinyai namaḥ', 'मुखं पूजयामि', 'Worship the face', 'முகம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 17, 'ॐ माहेश्वर्यै नमः', 'ஓம் மாஹேஶ்வர்யை நம꞉', 'oṃ māheśvaryai namaḥ', 'शिरः पूजयामि', 'Worship the head', 'ஶிர꞉ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 72), 18, 'ॐ कात्यायन्यै नमः', 'ஓம் காத்யாயந்யை நம꞉', 'oṃ kātyāyanyai namaḥ', 'सर्वाण्यंगानि पूजयामि', 'Worship the whole body', 'ஸர்வாண்யம்காநி பூஜயாமி');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 73, 'pradhana', '{main,punar,udvasana}', 'Archana', 'அர்ச்சனை', 'Durga Ashtottara Shatanamavali', 'துர்கா அஷ்டோத்தர ஶதநாமாவளி',
        'Offer a flower or a pinch of akshatai at each of the hundred and eight names of Durga. On Vijayadashami these names are recited again before the Goddess is released.',
        'துர்கையின் நூற்றெட்டு நாமங்களில் ஒவ்வொன்றிலும் ஒரு புஷ்பமோ சிறிது அக்ஷதையோ சமர்ப்பிக்கவும். விஜயதசமியன்று தேவியை யதாஸ்தானம் செய்வதற்கு முன் இந்த நாமங்கள் மீண்டும் சொல்லப்படுகின்றன.',
        null,
        null,
        null,
        'One hundred and eight names of Durga, opening with Shri, Uma and Bharati and closing with Durgaparameshvari, the supreme Durga. Many are names of Lakshmi and Saraswati as well, which is the point of saying them at Navaratri.',
        'The list begins with shriyai, the name of Lakshmi, and keeps returning to names of learning and speech. A hundred and eight names of Durga turn out to hold all three goddesses of the sankalpam.', 'all', true, false,
        'durga_ashtottara_108', 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja pp.293-296, durgaaSHTOttarashatanaamaavalihi, count markers verified in both scripts');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 74, 'pradhana', '{main,punar}', 'Archana', 'அர்ச்சனை', 'Lakshmi Ashtottara Shatanamavali', 'லக்ஷ்மி அஷ்டோத்தர ஶதநாமாவளி',
        'The hundred and eight names of Lakshmi follow the names of Durga. Offer a flower or akshatai at each. On a short day this and the next list may be left for the middle three days, when Lakshmi is especially worshipped.',
        'துர்கா நாமங்களைத் தொடர்ந்து லக்ஷ்மியின் நூற்றெட்டு நாமங்கள். ஒவ்வொன்றிலும் புஷ்பமோ அக்ஷதையோ சமர்ப்பிக்கவும். நேரம் குறைவான நாளில், லக்ஷ்மிக்கு உரிய நடு மூன்று நாட்களுக்கு இதை விட்டு வைக்கலாம்.',
        null,
        null,
        null,
        'One hundred and eight names of Lakshmi, beginning with Prakriti and Vikriti, nature and its transformation, and closing with Bhuvaneshvari, mistress of the worlds.',
        'The Durga list is followed by the lists of the other two goddesses the sankalpam named, so that each of the three is addressed by her own names as well as together.', 'all', true, false,
        'lakshmi_ashtottara_108', 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.296, rubric: the Lakshmi ashtottaram (book p.123), as carried for Varalakshmi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 75, 'pradhana', '{main,punar}', 'Archana', 'அர்ச்சனை', 'Saraswati Ashtottara Shatanamavali', 'ஸரஸ்வதீ அஷ்டோத்தர ஶதநாமாவளி',
        'Then the hundred and eight names of Saraswati, with a flower or akshatai at each. They are the same names said over the books on Saraswati Pooja.',
        'பின் ஸரஸ்வதியின் நூற்றெட்டு நாமங்கள், ஒவ்வொன்றிலும் புஷ்பமோ அக்ஷதையோ. ஸரஸ்வதீ பூஜையன்று புத்தகங்களின் மேல் சொல்லப்படும் அதே நாமங்கள் இவை.',
        null,
        null,
        null,
        'One hundred and eight names of Saraswati, opening with Saraswati and Mahabhadra and closing with Brahmavishnushivatmika, she who is the self of Brahma, Vishnu and Shiva.',
        'The last of the three lists ends by naming her as the self of the whole trinity, which is a fitting place for a Navaratri archana to stop.', 'all', true, false,
        'saraswati_ashtottara_108', 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.296, rubric: the Saraswati ashtottaram, pp.315-318');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 76, 'pradhana', '{main,punar,udvasana}', 'Archana', 'அர்ச்சனை', 'Patra Pushpa Samarpanam', 'பத்ர புஷ்ப ஸமர்ப்பணம்',
        'After the last of the names, offer the rest of the flowers and leaves to the Goddess in one handful.',
        'நாமங்கள் முடிந்ததும், மீதமுள்ள புஷ்பங்களையும் இலைகளையும் ஒரே கைப்பிடியாகத் தேவிக்குச் சமர்ப்பிக்கவும்.',
        'नानाविध परिमलपत्रपुष्पाणि समर्पयामि',
        'நாநாவித பரிமலபத்ரபுஷ்பாணி ஸமர்பயாமி',
        'nānāvidha parimalapatrapuṣpāṇi samarpayāmi',
        'I offer fragrant leaves and flowers of many kinds.',
        'The lists end as the Vighneshwara archana ended, with everything left offered at once: three goddesses'' names, closed by a single handful.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.294, the close of the archana; the roman (p.296) reads puSHpaaNi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 77, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Dhoopam', 'தூபம்',
        'Light the incense and wave it before the Goddess.',
        'ஊதுபத்தியை ஏற்றி தேவியின் முன் காட்டவும்.',
        'दशाङ्गं गुग्गुलोपेतं चन्दनागरु संयुतम्।
समर्पितं मया भक्त्या महादेवि प्रतिगृह्यताम्।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः धूपं आघ्रापयामि ।',
        'தஶாங்கம் குக்குலோபேதம் சந்தநாகரு ஸம்யுதம்।
ஸமர்பிதம் மயா பக்த்யா மஹாதேவி ப்ரதிக்ருஹ்யதாம்।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ தூபம் ஆக்ராபயாமி ।',
        'daśāṅgaṃ guggulopetaṃ candanāgaru saṃyutam।
samarpitaṃ mayā bhaktyā mahādevi pratigṛhyatām।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ dhūpaṃ āghrāpayāmi ।',
        'Incense of ten ingredients with guggulu, sandal and aloe wood, offered by me with devotion: receive it, great Goddess. Salutations to Sri Durga, Lakshmi and Saraswati: I offer incense.',
        'Dashanga, "of ten parts". Incense in the old recipes is a compound of many fragrances, and the verse names them as a host would describe a dish made specially.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.297, uttaraanga poojaa, dhoopam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 78, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Deepam', 'தீபம்',
        'Wave the ghee lamp before her.',
        'நெய் தீபத்தை அவள் முன் காட்டவும்.',
        'साज्यं त्रिवर्त्तिसंयुक्तं महातेजो महोज्वलम्।
दीपं दास्यामि देवेशि सुप्रीता भव सर्वदा।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः दीपं दर्शयामि',
        'ஸாஜ்யம் த்ரிவர்த்திஸம்யுக்தம் மஹாதேஜோ மஹோஜ்வலம்।
தீபம் தாஸ்யாமி தேவேஶி ஸுப்ரீதா பவ ஸர்வதா।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ தீபம் தர்ஶயாமி',
        'sājyaṃ trivarttisaṃyuktaṃ mahātejo mahojvalam।
dīpaṃ dāsyāmi deveśi suprītā bhava sarvadā।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ dīpaṃ darśayāmi',
        'A lamp with ghee and three wicks, of great brilliance and blaze: I give it to you, Queen of the gods; be pleased always. Salutations to Sri Durga, Lakshmi and Saraswati: I show the lamp.',
        'Trivarti, "three wicks". The lamp offered to the three goddesses has a wick for each of them, which is why a Navaratri lamp is so often a three-wick one.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.297, deepam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 79, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Dhoopa Deepa Achamaniyam', 'தூப தீபாநந்தர ஆசமனீயம்',
        'Offer an uddharani of water.',
        'ஒரு உத்தரிணி ஜலம் சமர்ப்பிக்கவும்.',
        'धूप,दीपानन्तरं आचमनीयं समर्पयामि ।',
        'தூப,தீபாநந்தரம் ஆசமநீயம் ஸமர்பயாமி ।',
        'dhūpa,dīpānantaraṃ ācamanīyaṃ samarpayāmi ।',
        'After the incense and the lamp, I offer water to sip.',
        'The same water that closed the incense and lamp for Vighneshwara closes them for the Goddess. The grammar of the rite does not change with the size of the guest.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.297, dhoopa deepaanantaram aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 80, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Naivedya Prokshanam', 'நைவேத்ய ப்ரோக்ஷணம்',
        'Set the food on a plate or a plantain leaf on a spot cleaned with a little water, in front of the Goddess. Sprinkle water over it with the first line; as you recite the Gayatri, take water in the uddharani and circle the plate clockwise three times.',
        'தேவியின் முன், சிறிது ஜலத்தால் சுத்தம் செய்த இடத்தில், தட்டிலோ வாழையிலையிலோ நைவேத்யத்தை வைக்கவும். முதல் வரியுடன் அதன் மேல் ஜலம் தெளிக்கவும்; காயத்ரீ சொல்லும்போது உத்தரிணியில் ஜலம் எடுத்து, தட்டை மூன்று முறை வலமாகச் சுற்றவும்.',
        'ॐ भूर्भुवस्सुवः
तत्सवितुर्वरेण्यं भर्गोदेवस्य धीमहि, धियो यो नः प्रचोदयात्',
        'ஓம் பூர்புவஸ்ஸுவ꞉
தத்ஸவிதுர்வரேண்யம் பர்கோதேவஸ்ய தீமஹி, தியோ யோ ந꞉ ப்ரசோதயாத்',
        'oṃ bhūrbhuvassuvaḥ
tatsaviturvareṇyaṃ bhargodevasya dhīmahi, dhiyo yo naḥ pracodayāt',
        'Om, earth, sky, heaven. We meditate on the glorious light of the divine Savitr; may it inspire our minds.',
        'The Goddess''s meal is purified with the Gayatri, the same verse the karta held their breath through at the start. The words that steadied the worshipper now make the food fit for her.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.298, naivEdyamantraaha: the sprinkling and the threefold circling');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 81, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Parishechanam', 'பரிஷேசனம்',
        'Take a little water again and circle the plate clockwise while saying this: the first line in the morning, the second in the evening.',
        'மீண்டும் சிறிது ஜலம் எடுத்து, இதைச் சொல்லியபடி தட்டை வலமாகச் சுற்றவும்: காலையில் முதல் வரி, மாலையில் இரண்டாம் வரி.',
        'देवसवितः प्रसुव। सत्यं त्वर्तेन परिषिञ्चामि।
देवसवितः प्रसुव। ऋतं त्वा सत्येन परिषिञ्चामि।',
        'தேவஸவித꞉ ப்ரஸுவ। ஸத்யம் த்வர்தேந பரிஷிஞ்சாமி।
தேவஸவித꞉ ப்ரஸுவ। ருதம் த்வா ஸத்யேந பரிஷிஞ்சாமி।',
        'devasavitaḥ prasuva। satyaṃ tvartena pariṣiñcāmi।
devasavitaḥ prasuva। ṛtaṃ tvā satyena pariṣiñcāmi।',
        'Divine Savitr, impel us. Morning: I sprinkle you, truth, with order. Evening: I sprinkle you, order, with truth.',
        'Navaratri pooja may be done in the morning or at dusk, and the ring of water around the food knows which. Satya and rita, truth and order, simply change places.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.298, the morning and evening parishechana lines');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 82, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Amritopastaranam', 'அம்ருதோபஸ்தரணம்',
        'Offer a spoon of water into the plate.',
        'ஒரு உத்தரிணி ஜலத்தைத் தாம்பாளத்தில் விடவும்.',
        'अमृतोपस्तरणमसि ।',
        'அம்ருதோபஸ்தரணமஸி ।',
        'amṛtopastaraṇamasi ।',
        'You are the immortal bed for the food.',
        'A spoon of water laid down before the meal as its bed. However grand the naivedyam, it rests on the same simple water as a single fruit would.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.298, amRtOpastaraNamasi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 83, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Pranahuti', 'ப்ராணாஹுதி',
        'After each svaha, gesture with the right hand as if feeding the Goddess from the plate.',
        'ஒவ்வொரு ஸ்வாஹாவிற்குப் பின்னும், தட்டிலிருந்து தேவிக்கு ஊட்டுவது போல் வலது கையால் காட்டவும்.',
        'ॐ प्राणाय स्वाहा, ॐ अपानाय स्वाहा, ॐ व्यानाय स्वाहा,
ॐ उदानाय स्वाहा, ॐ समानाय स्वाहा, ॐ ब्रह्मणे स्वाहा।',
        'ஓம் ப்ராணாய ஸ்வாஹா, ஓம் அபாநாய ஸ்வாஹா, ஓம் வ்யாநாய ஸ்வாஹா,
ஓம் உதாநாய ஸ்வாஹா, ஓம் ஸமாநாய ஸ்வாஹா, ஓம் ப்ரஹ்மணே ஸ்வாஹா।',
        'oṃ prāṇāya svāhā, oṃ apānāya svāhā, oṃ vyānāya svāhā,
oṃ udānāya svāhā, oṃ samānāya svāhā, oṃ brahmaṇe svāhā।',
        'Om, to prana, svaha; to apana, vyana, udana and samana, svaha; to Brahman, svaha.',
        'Six mouthfuls, offered to the breaths of life and to Brahman, before the food is named. The Goddess is fed as one feeds the life in a body, not as one leaves a plate at a shrine.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.298, the six praaNaahutis');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 84, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Mahanaivedyam', 'மஹாநைவேத்யம்',
        'Offer the food to the Goddess.',
        'நைவேத்யத்தைத் தேவிக்கு நிவேதனம் செய்யவும்.',
        'अन्नम् चतुर्विधं स्वादु षड्रसैः सुसमन्वितम्।
नैवेद्यं गृह्यतां देवि भक्तिं मे ह्यचलां कुरु।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः महानैवेद्यं निवेदयामि',
        'அந்நம் சதுர்விதம் ஸ்வாது ஷட்ரஸை꞉ ஸுஸமந்விதம்।
நைவேத்யம் க்ருஹ்யதாம் தேவி பக்திம் மே ஹ்யசலாம் குரு।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ மஹாநைவேத்யம் நிவேதயாமி',
        'annam caturvidhaṃ svādu ṣaḍrasaiḥ susamanvitam।
naivedyaṃ gṛhyatāṃ devi bhaktiṃ me hyacalāṃ kuru।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ mahānaivedyaṃ nivedayāmi',
        'Food of four kinds, sweet and rich in the six tastes: receive this offering, Goddess, and make my devotion unshakeable. Salutations to Sri Durga, Lakshmi and Saraswati: I offer the great food offering.',
        'Bhaktim me hyachalam kuru, "make my devotion unshakeable". The one thing asked in return for the meal is not a favour but steadiness, which over nine days of the same pooja is the thing most likely to run out.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja pp.298-299, mahaanaivEdyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 85, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Amritapaniyam', 'அம்ருதபானீயம்',
        'Offer a spoon of water, as water to drink with the meal.',
        'உணவுடன் அருந்தும் ஜலமாக ஒரு உத்தரிணி ஜலம் சமர்ப்பிக்கவும்.',
        'मध्ये मध्ये अमृतपानीयं समर्पयामि ।',
        'மத்யே மத்யே அம்ருதபாநீயம் ஸமர்பயாமி ।',
        'madhye madhye amṛtapānīyaṃ samarpayāmi ।',
        'Now and again during the meal, I offer water, sweet as nectar, to drink.',
        'The Goddess is not left to eat in silence with an empty cup. Water is offered in the middle of the meal, as a host would pour it for a guest at the table.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.299, madhyE madhyE amRtapaaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 86, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Achamaniyam after Naivedyam', 'நிவேதனாநந்தர ஆசமனீயம்',
        'Offer a spoon of water, to rinse after the meal.',
        'உணவுக்குப் பின் வாய் கழுவ ஒரு உத்தரிணி ஜலம் சமர்ப்பிக்கவும்.',
        'निवेदनानन्तरं आचमनीयं समर्पयामि ।',
        'நிவேதநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி ।',
        'nivedanānantaraṃ ācamanīyaṃ samarpayāmi ।',
        'After the offering of food, I offer water to sip.',
        'The meal ends where every meal in the house ends, with water to rinse. Nothing in the order of eating is skipped because the guest is divine.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.299, nivEdanaanantaram aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 87, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Tambulam', 'தாம்பூலம்',
        'Sprinkle a little water on the betel leaves and areca nut, and offer them.',
        'வெற்றிலை பாக்கின் மேல் சிறிது ஜலம் தெளித்துச் சமர்ப்பிக்கவும்.',
        'एलालवङ्ग कस्तूरी कर्पूरैः पुण्यवासितम्।
वीटिकां मुखवासार्थं अर्पयामि सुरेश्वरि।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कर्पूरताम्बूलं समर्पयामि।।',
        'ஏலாலவங்க கஸ்தூரீ கர்பூரை꞉ புண்யவாஸிதம்।
வீடிகாம் முகவாஸார்தம் அர்பயாமி ஸுரேஶ்வரி।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கர்பூரதாம்பூலம் ஸமர்பயாமி।।',
        'elālavaṅga kastūrī karpūraiḥ puṇyavāsitam।
vīṭikāṃ mukhavāsārthaṃ arpayāmi sureśvari।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ karpūratāmbūlaṃ samarpayāmi।।',
        'A betel roll made fragrant with cardamom, clove, musk and camphor, to sweeten the mouth: I offer it, Queen of the gods. Salutations to Sri Durga, Lakshmi and Saraswati: I offer betel with camphor.',
        'Tambulam ends a meal in a South Indian house, and it ends the Goddess''s meal too. It is the host''s sign that the guest has been fed fully.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.299, karpoorataamboolam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 88, 'uttara', '{udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Karpura Neerajanam', 'கற்பூர நீராஜனம்',
        'Before the Goddess is sent home, light camphor and wave it clockwise in front of the kalasham or image.',
        'தேவிக்கு விடை கொடுப்பதற்கு முன், கற்பூரம் ஏற்றி கலசத்தின் அல்லது விக்ரஹத்தின் முன் வலமாகச் சுற்றிக் காட்டவும்.',
        'कृतवर्ति सहस्रैश्च कर्पूर शकलैस्तदा।
नीराजनं मया दत्तं गृहाण वरदा भव ।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कर्पूरनीराजनं दर्शयामि।।',
        'க்ருதவர்தி ஸஹஸ்ரைஶ்ச கர்பூர ஶகலைஸ்ததா।
நீராஜநம் மயா தத்தம் க்ருஹாண வரதா பவ ।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கர்பூரநீராஜநம் தர்ஶயாமி।।',
        'kṛtavarti sahasraiśca karpūra śakalaistadā।
nīrājanaṃ mayā dattaṃ gṛhāṇa varadā bhava ।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ karpūranīrājanaṃ darśayāmi।।',
        'Lit with a thousand wicks and pieces of camphor, this waving of light is offered by me: receive it and be a giver of boons. Salutations to Sri Durga, Lakshmi and Saraswati: I show the camphor flame.',
        'On the last morning the camphor is the final light the Goddess is shown in this house. It burns out completely and leaves nothing behind, which is the right thing to wave just before asking her to go and to come again.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.304 rubric for dashami (wave camphor); verse from p.321, addressed to the same three goddesses');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 89, 'uttara', '{udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Achamaniyam after Neerajanam', 'நீராஜனாநந்தர ஆசமனீயம்',
        'Offer an uddharani of water after the camphor.',
        'கற்பூரத்திற்குப் பின் ஒரு உத்தரிணி ஜலம் சமர்ப்பிக்கவும்.',
        'नीराजनानन्तरं आचमनीयं समर्पयामि',
        'நீராஜநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி',
        'nīrājanānantaraṃ ācamanīyaṃ samarpayāmi',
        'After the waving of light, I offer water to sip.',
        'Even on the last morning the order of service is kept to the end: light, then water, as on every other day.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Saraswati Puja p.322, neeraajanaanantaram aachamaneeyam, with the camphor above');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 90, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Pushpanjali', 'புஷ்பாஞ்ஜலி',
        'Take flowers and akshatai in both cupped hands, recite, and offer them at her feet. Everyone present may offer flowers.',
        'இரு கைகளையும் குவித்து புஷ்பமும் அக்ஷதையும் எடுத்து, ஸ்லோகம் சொல்லி அவள் பாதத்தில் சமர்ப்பிக்கவும். அங்கிருக்கும் அனைவரும் புஷ்பம் சமர்ப்பிக்கலாம்.',
        'मन्दार पारिजातादि पाटली केतकानि च।
जाती चंपक पुष्पाणि गृहाणेमानि शोभने।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः पुष्पाञ्जलिं समर्पयामि।।',
        'மந்தார பாரிஜாதாதி பாடலீ கேதகாநி ச।
ஜாதீ சம்பக புஷ்பாணி க்ருஹாணேமாநி ஶோபநே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ புஷ்பாஞ்ஜலிம் ஸமர்பயாமி।।',
        'mandāra pārijātādi pāṭalī ketakāni ca।
jātī caṃpaka puṣpāṇi gṛhāṇemāni śobhane।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ puṣpāñjaliṃ samarpayāmi।।',
        'Mandara, parijata, patali and ketaki, jasmine and champaka: receive these flowers, radiant one. Salutations to Sri Durga, Lakshmi and Saraswati: I offer a handful of flowers.',
        'The only step of the pooja that is handed to everyone in the room. Navaratri is a household festival with guests coming and going, and the flowers are how the visitors take part in the worship rather than watching it.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.299, puSHpaanjali');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 91, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Pradakshina & Namaskaram', 'ப்ரதக்ஷிணம் & நமஸ்காரம்',
        'With palms joined, go round the Goddess clockwise three times, or stand and turn clockwise three times where you are. Then prostrate: men with eight limbs touching the ground, women with five.',
        'கைகூப்பியபடி தேவியை மூன்று முறை வலம் வரவும்; இடமில்லையெனில் நின்ற இடத்திலேயே மூன்று முறை வலமாகச் சுற்றவும். பின் நமஸ்கரிக்கவும் — ஆண்கள் ஸாஷ்டாங்கமாக (எட்டு அங்கங்கள் தரையில் பட), பெண்கள் பஞ்சாங்கமாக (ஐந்து அங்கங்கள்).',
        'दुर्गे स्मृता हरसि भीतिमशेष-जन्तोः।
स्वस्थैः स्मृता मतिमतीव शुभां ददासि।।
दारिद्र्यदुःखभयहारिणि का त्वदन्या।
सर्वोपकारकरणाय सदार्द्रचित्ता।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः प्रदक्षिणनमस्कारान् समर्पयामि।।',
        'துர்கே ஸ்ம்ருதா ஹரஸி பீதிமஶேஷ-ஜந்தோ꞉।
ஸ்வஸ்தை꞉ ஸ்ம்ருதா மதிமதீவ ஶுபாம் ததாஸி।।
தாரித்ர்யது꞉கபயஹாரிணி கா த்வதந்யா।
ஸர்வோபகாரகரணாய ஸதார்த்ரசித்தா।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ப்ரதக்ஷிணநமஸ்காராந் ஸமர்பயாமி।।',
        'durge smṛtā harasi bhītimaśeṣa-jantoḥ।
svasthaiḥ smṛtā matimatīva śubhāṃ dadāsi।।
dāridryaduḥkhabhayahāriṇi kā tvadanyā।
sarvopakārakaraṇāya sadārdracittā।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ pradakṣiṇanamaskārān samarpayāmi।।',
        'Durga, remembered, you take away the fear of every creature; remembered by those at ease, you give them a mind more blessed still. Remover of poverty, sorrow and fear, who but you has a heart always soft with the wish to help everyone? Salutations to Sri Durga, Lakshmi and Saraswati: I offer circumambulation and prostrations.',
        'This verse is from the Devi Mahatmyam, the text recited through Navaratri. Smrta, "remembered", carries it: she does not need to be summoned with ceremony, only remembered, and the circling is a way of keeping her at the centre while doing it.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.300, pradakSHiNa namaskaaraan; three rounds and the eight- and five-limbed prostration from the general instructions, p.XVI');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 92, 'uttara', '{main,punar}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Navadurga Pooja', 'நவதுர்கா பூஜை',
        'Offer a flower at each of the nine forms of Durga, from Shailaputri to Siddhidatri. On each day of Navaratri the form for that day may be honoured with an extra flower: Shailaputri on the first, Siddhidatri on the ninth.',
        'துர்கையின் ஒன்பது வடிவங்களுக்கும், ஶைலபுத்ரீ முதல் ஸித்திதாத்ரீ வரை, ஒவ்வொன்றிற்கும் ஒரு புஷ்பம் சமர்ப்பிக்கவும். நவராத்திரியின் ஒவ்வொரு நாளும் அந்நாளுக்கு உரிய வடிவத்திற்கு கூடுதலாக ஒரு புஷ்பம் சமர்ப்பிக்கலாம் — முதல் நாள் ஶைலபுத்ரீ, ஒன்பதாம் நாள் ஸித்திதாத்ரீ.',
        null,
        null,
        null,
        'Salutations to the nine Durgas: Shailaputri, daughter of the mountain; Brahmacharini, the ascetic; Chandraghanta, crowned with the crescent; Kushmanda, who laughed the universe into being; Skandamata, mother of Skanda; Katyayani; Kalaratri, the night of time; Mahagauri, the radiant; and Siddhidatri, giver of attainment.',
        'The nine forms run in a line from a girl, the mountain''s daughter, through the ascetic, the warrior and the mother, to the one who grants completion. Read in order they are a life, which is why there is one for each night.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.300, navadurgaa poojaa; two-column list read in the canonical order of the nine forms');

insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit,
   offering_deva, offering_en, offering_ta)
values
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 1, 'ॐ शैलपुत्र्यै नमः', 'ஓம் ஶைலபுத்ர்யை நம꞉', 'oṃ śailaputryai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 2, 'ॐ ब्रह्मचारिण्यै नमः', 'ஓம் ப்ரஹ்மசாரிண்யை நம꞉', 'oṃ brahmacāriṇyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 3, 'ॐ चन्द्रघण्टायै नमः', 'ஓம் சந்த்ரகண்டாயை நம꞉', 'oṃ candraghaṇṭāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 4, 'ॐ कूष्माण्डायै नमः', 'ஓம் கூஷ்மாண்டாயை நம꞉', 'oṃ kūṣmāṇḍāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 5, 'ॐ स्कन्दमात्रे नमः', 'ஓம் ஸ்கந்தமாத்ரே நம꞉', 'oṃ skandamātre namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 6, 'ॐ कात्यायिन्यै नमः', 'ஓம் காத்யாயிந்யை நம꞉', 'oṃ kātyāyinyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 7, 'ॐ कालरात्र्यै नमः', 'ஓம் காலராத்ர்யை நம꞉', 'oṃ kālarātryai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 8, 'ॐ महागौर्यै नमः', 'ஓம் மஹாகௌர்யை நம꞉', 'oṃ mahāgauryai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 92), 9, 'ॐ सिद्धिदायै नमः', 'ஓம் ஸித்திதாயை நம꞉', 'oṃ siddhidāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 93, 'uttara', '{main,punar}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Jyoti Pooja', 'ஜ்யோதி பூஜை',
        'Offer flowers and akshatai to the lamp itself. The lamp lit on the first day is kept burning, or lit afresh at each pooja, through all nine days.',
        'தீபத்திற்கே புஷ்பமும் அக்ஷதையும் சமர்ப்பிக்கவும். முதல் நாள் ஏற்றிய தீபம் ஒன்பது நாட்களும் அணையாமல் வைக்கப்படுகிறது, அல்லது ஒவ்வொரு பூஜையிலும் புதிதாக ஏற்றப்படுகிறது.',
        'प्रधान साधार विकल्पसत्ता स्वभावभावात् भुवनत्रयस्य।
सा विद्यया व्यक्तमपीह माया ज्योतिः परा पातु जगन्ति नित्यम्।।
तेजस्स्वरूपायै श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः',
        'ப்ரதாந ஸாதார விகல்பஸத்தா ஸ்வபாவபாவாத் புவநத்ரயஸ்ய।
ஸா வித்யயா வ்யக்தமபீஹ மாயா ஜ்யோதி꞉ பரா பாது ஜகந்தி நித்யம்।।
தேஜஸ்ஸ்வரூபாயை ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉',
        'pradhāna sādhāra vikalpasattā svabhāvabhāvāt bhuvanatrayasya।
sā vidyayā vyaktamapīha māyā jyotiḥ parā pātu jaganti nityam।।
tejassvarūpāyai śrīdurgā lakṣmī sarasvatī devyai namaḥ',
        'She who, by her own nature, is the reality behind the three worlds, their ground and all their variety; the Maya made manifest here by knowledge: may that supreme light protect the worlds always. Salutations to Sri Durga, Lakshmi and Saraswati, whose form is radiance.',
        'Tejassvarupa, "whose form is radiance". The lamp is not a light shown to the Goddess here; it is worshipped as her. That is why it is kept burning through the nine nights rather than lit and put out with each pooja.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja pp.300-301, jyOti poojaa');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 94, 'uttara', '{main,punar,udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Prarthana', 'ப்ரார்த்தனை',
        'With joined hands, pray to the Goddess.',
        'கைகூப்பி தேவியைப் ப்ரார்த்திக்கவும்.',
        'सर्वमङ्गल माङ्गल्ये शिवे सर्वार्थ साधिके।
शरण्ये त्र्यम्बके गौरि नारायणि नमोऽस्तु ते।।
रूपं देहि याशो देहि भगं भगवति देहि मे।
पुत्रान् देहि धनं देहि सर्वान् कामान् प्रदेहि मे।।',
        'ஸர்வமங்கல மாங்கல்யே ஶிவே ஸர்வார்த ஸாதிகே।
ஶரண்யே த்ர்யம்பகே கௌரி நாராயணி நமோஸ்து தே।।
ரூபம் தேஹி யாஶோ தேஹி பகம் பகவதி தேஹி மே।
புத்ராந் தேஹி தநம் தேஹி ஸர்வாந் காமாந் ப்ரதேஹி மே।।',
        'sarvamaṅgala māṅgalye śive sarvārtha sādhike।
śaraṇye tryambake gauri nārāyaṇi namo''stu te।।
rūpaṃ dehi yāśo dehi bhagaṃ bhagavati dehi me।
putrān dehi dhanaṃ dehi sarvān kāmān pradehi me।।',
        'Auspiciousness of all that is auspicious, Shiva, fulfiller of every aim, refuge, three-eyed Gauri, Narayani: salutations to you. Give me beauty, give me fame, give me good fortune, Goddess; give me children, give me wealth, give me all that I desire.',
        'Sarvamangala mangalye is the best known verse of the Devi Mahatmyam and the plainest. After nine days of upacharas it simply asks, out loud, for what a household wants. There is no embarrassment in the asking.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.301, praarthanaa');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 95, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Avahanam', 'கன்யா ஆவாஹனம்',
        'Seat a girl younger than twelve before you and invoke the Goddess in her with this verse. Usually one girl is honoured each day, or nine together on one day.',
        'பன்னிரண்டு வயதிற்குட்பட்ட ஒரு சிறுமியை முன்னே அமர வைத்து, இந்த ஸ்லோகத்தால் அவளிடம் தேவியை ஆவாஹனம் செய்யவும். பொதுவாக ஒவ்வொரு நாளும் ஒரு சிறுமி, அல்லது ஒரு நாளில் ஒன்பது பேர் சேர்ந்து.',
        'ॐ क्लीं कुलकुमारिकायै नमः
मन्त्राक्षरमयीं लक्ष्मीं मातृणांरूपधारिणीम्।
नवदुर्गात्मिकां साक्षात् कन्यामावाहयाम्यहम्।।',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
மந்த்ராக்ஷரமயீம் லக்ஷ்மீம் மாத்ருணாம்ரூபதாரிணீம்।
நவதுர்காத்மிகாம் ஸாக்ஷாத் கந்யாமாவாஹயாம்யஹம்।।',
        'oṃ klīṃ kulakumārikāyai namaḥ
mantrākṣaramayīṃ lakṣmīṃ mātṛṇāṃrūpadhāriṇīm।
navadurgātmikāṃ sākṣāt kanyāmāvāhayāmyaham।।',
        'Om klim, salutations to the maiden of the family. I invoke the maiden who is Lakshmi made of the letters of the mantra, who bears the form of the mothers, the nine Durgas in person.',
        'Every other step of the pooja treats an image as the Goddess. This one treats a child as the Goddess, and gives her exactly the upacharas the kalasham received. It is the clearest statement in the whole festival of where the divine is supposed to be looked for.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.301, navakanyaa poojaa, the invocation');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 96, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Padyam', 'கன்யா பாத்யம்',
        'Offer water for the girl''s feet.',
        'சிறுமியின் பாதங்களுக்கு ஜலம் சமர்ப்பிக்கவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
पाद्यं समर्पयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
பாத்யம் ஸமர்பயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
pādyaṃ samarpayāmi',
        'Om klim, salutations to the maiden of the family: I offer water for the feet.',
        'The child''s feet are washed as the Goddess''s were. In most houses it is the elders who wash the young; here the order is reversed.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.302, paadyam, said to kulakumaarikaa');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
