values ('navaratri_pooja', 97, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Arghyam', 'கன்யா அர்க்யம்',
        'Offer water for her hands.',
        'அவள் கைகளுக்கு ஜலம் சமர்ப்பிக்கவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
अर्घ्यं समर्पयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
அர்க்யம் ஸமர்பயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
arghyaṃ samarpayāmi',
        'Om klim, salutations to the maiden of the family: I offer arghyam.',
        'Arghyam is the water of honour. Given to a girl of eight, it says plainly that honour here does not wait on age.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.302, arghyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
