values ('navaratri_pooja', 98, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Achamaniyam', 'கன்யா ஆசமனீயம்',
        'Offer her water to sip.',
        'அவள் அருந்துவதற்கு ஜலம் சமர்ப்பிக்கவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
आचमनीयं समर्पयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
ஆசமநீயம் ஸமர்பயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
ācamanīyaṃ samarpayāmi',
        'Om klim, salutations to the maiden of the family: I offer water to sip.',
        'Water to drink, offered with a mantra. The plainest act of hospitality is lifted to worship simply by being said.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.302, aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
