haridrākuṅkumaṃ samarpayāmi',
        'Om klim, salutations to the maiden of the family: I offer turmeric and kumkumam.',
        'Turmeric and kumkumam are the marks of auspiciousness every girl and woman who visits at Navaratri goes home with. Here they are given as worship, not only as courtesy.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.302, haridraakunkumam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
