values ('navaratri_pooja', 103, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Pushpam', 'கன்யா புஷ்பம்',
        'Offer her flowers.',
        'அவளுக்குப் புஷ்பம் சமர்ப்பிக்கவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
पुष्पाणि समर्पयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
புஷ்பாணி ஸமர்பயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
puṣpāṇi samarpayāmi',
        'Om klim, salutations to the maiden of the family: I offer flowers.',
        'Flowers in a child''s hair are an ordinary festival sight. Offered with the mantra, they become the flowers of a pooja.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.302, puSHpaaNi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
