   namavali_id, source_ref)
values ('navaratri_pooja', 104, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Navakanya Pooja', 'நவகன்யா பூஜை',
        'Offer a flower at each of the nine names of the maiden, from Kumari to Subhadra.',
        'கன்னிகையின் ஒன்பது நாமங்களுக்கும், குமாரீ முதல் ஸுபத்ரா வரை, ஒவ்வொன்றிற்கும் ஒரு புஷ்பம் சமர்ப்பிக்கவும்.',
        null,
        null,
        null,
        'Salutations to Kaumari, Tripura, Kalyani, Rohini, Kamini, Chandika, Shankari, Durga and Subhadra: the nine maidens, named by age.',
        'The nine names are the ages of girlhood, each a form of the Goddess. The one girl before you is honoured as all nine at once.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja pp.302-303, archanaa; the nine names read in the order of the maidens'' ages, Kumari to Subhadra');

