insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 105, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Dhoopam', 'கன்யா தூபம்',
        'Show her incense.',
        'அவளுக்குத் தூபம் காட்டவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
धूपं आघ्रापयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
தூபம் ஆக்ராபயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
dhūpaṃ āghrāpayāmi',
        'Om klim, salutations to the maiden of the family: I offer incense.',
        'Incense is waved for a child just as it is waved for the deity. Nothing in the pooja marks her as a lesser guest.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.303, dhoopam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 106, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Deepam', 'கன்யா தீபம்',
        'Show her a lamp with a wick dipped in ghee.',
        'நெய்யில் நனைத்த திரியுடன் ஏற்றிய தீபத்தை அவளுக்குக் காட்டவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
दीपं दर्शयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
தீபம் தர்ஶயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
dīpaṃ darśayāmi',
        'Om klim, salutations to the maiden of the family: I show the lamp.',
        'The lamp is shown to her face. It is the moment the household looks at the child and sees the Goddess there.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.303, deepam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 107, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Naivedyam', 'கன்யா நைவேத்யம்',
        'Offer her food.',
        'அவளுக்கு உணவு அளிக்கவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
नैवेद्यं निवेदयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
நைவேத்யம் நிவேதயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
naivedyaṃ nivedayāmi',
        'Om klim, salutations to the maiden of the family: I offer food.',
        'The naivedyam set before the kalasham is a gesture; the food set before the girl is eaten. In this step the offering really is received.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.303, naivEdyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 108, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Achamaniyam after Naivedyam', 'கன்யா நிவேதனாநந்தர ஆசமனீயம்',
        'Offer her water after the food.',
        'உணவுக்குப் பின் அவளுக்கு ஜலம் சமர்ப்பிக்கவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
निवेदनानन्तरं आचमनीयं समर्पयामि।',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
நிவேதநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி।',
        'oṃ klīṃ kulakumārikāyai namaḥ
nivedanānantaraṃ ācamanīyaṃ samarpayāmi।',
        'Om klim, salutations to the maiden of the family: after the food, I offer water to sip.',
        'She is given water after eating, as any guest at the table is. The rite and ordinary good manners are the same thing here.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.303, nivEdanaanantaram aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 109, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Neerajanam', 'கன்யா நீராஜனம்',
        'Wave lit camphor before her, clockwise.',
        'கற்பூரம் ஏற்றி அவள் முன் வலமாகச் சுற்றிக் காட்டவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
कर्पूर नीराजनम् समर्पयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
கர்பூர நீராஜநம் ஸமர்பயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
karpūra nīrājanam samarpayāmi',
        'Om klim, salutations to the maiden of the family: I offer the camphor light.',
        'Aarti for a child is common enough on a birthday. Here it is done in earnest, to the Goddess in her.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.303, karpoora neeraajanam, rubric: offer camphor light');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 110, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Achamaniyam after Neerajanam', 'கன்யா நீராஜனாநந்தர ஆசமனீயம்',
        'Offer her water after the camphor.',
        'கற்பூரத்திற்குப் பின் அவளுக்கு ஜலம் சமர்ப்பிக்கவும்.',
        'ॐ क्लीं कुलकुमारिकायै नमः
नीराजनानन्तरं आचमनीयं समर्पयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
நீராஜநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
nīrājanānantaraṃ ācamanīyaṃ samarpayāmi',
        'Om klim, salutations to the maiden of the family: after the light, I offer water to sip.',
        'Light and then water, the same close the Goddess received. The kanya pooja keeps the full order of service to its last step.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.303, neeraajanaanantaram aachamaneeyam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 111, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை', 'Kanya Prarthana', 'கன்யா ப்ரார்த்தனை',
        'With joined hands, pray to the Goddess in the girl. Then send her home with a gift.',
        'கைகூப்பி, சிறுமியிடம் உள்ள தேவியைப் ப்ரார்த்திக்கவும். பின் ஒரு பரிசு கொடுத்து அவளை அனுப்பவும்.',
        'रूपं देहि जयं देहि यशो देहि द्विषो जहि।
महिषघ्नि महामाये चामुण्डे मुण्डमालिनि।
आयुरारोग्यमैश्वर्यं देहि देवि नमोऽस्तु ते।। प्रार्थनां समर्पयामि',
        'ரூபம் தேஹி ஜயம் தேஹி யஶோ தேஹி த்விஷோ ஜஹி।
மஹிஷக்நி மஹாமாயே சாமுண்டே முண்டமாலிநி।
ஆயுராரோக்யமைஶ்வர்யம் தேஹி தேவி நமோஸ்து தே।। ப்ரார்தநாம் ஸமர்பயாமி',
        'rūpaṃ dehi jayaṃ dehi yaśo dehi dviṣo jahi।
mahiṣaghni mahāmāye cāmuṇḍe muṇḍamālini।
āyurārogyamaiśvaryaṃ dehi devi namo''stu te।। prārthanāṃ samarpayāmi',
        'Give me beauty, give me victory, give me fame, destroy my enemies, slayer of Mahisha, great Maya, Chamunda garlanded with skulls; give me long life, health and prosperity, Goddess: salutations to you. I offer my prayer.',
        'Rupam dehi jayam dehi yasho dehi dvisho jahi is the refrain of the Argala Stotram, said before the Devi Mahatmyam is read. It is said here to a child, which keeps the asking honest.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.303, praarthanaam samarpayaami');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 112, 'uttara', '{udvasana}', 'Uttaranga Pooja', 'உத்தராங்க பூஜை', 'Punah Pooja & Yathasthanam', 'புனர் பூஜை & யதாஸ்தானம்',
        'Pray to the Goddess with this verse and prostrate. Then move the kalasham or image a little towards the north: she is sent home with an invitation to come back next year.',
        'இந்த ஸ்லோகத்தால் தேவியைப் ப்ரார்த்தித்து நமஸ்கரிக்கவும். பின் கலசத்தையோ விக்ரஹத்தையோ வடக்குப் பக்கம் சிறிது நகர்த்தவும்: அடுத்த ஆண்டு மீண்டும் வர அழைத்து தேவிக்கு விடை கொடுக்கப்படுகிறது.',
        'उत्तिष्ठ देवि चण्डेशि शुभां पूजां प्रगृह्य।
कुरुष्व मे हि कल्याणं अष्टभिः शक्तिभिः सह।।
दुर्गेलक्ष्मी च वाग्देवि स्वस्थानं गच्छ पूजिते।
संवत्सरे व्यतीते तु पुनरागमनाय वै।।
इमां पूजां मया देवि यथाशक्ति उपपादिताम्।
रक्षार्थं त्वं समादाय व्रजस्व स्थानमुत्तमम् ।।
श्रीदुर्गां लक्ष्मीं सरस्वतीं यथास्थानं प्रतिष्ठापयामि।
शोभनार्थे क्षेमाय पुनरागमनाय च।।
नमस्कारान् समर्पयामि',
        'உத்திஷ்ட தேவி சண்டேஶி ஶுபாம் பூஜாம் ப்ரக்ருஹ்ய।
குருஷ்வ மே ஹி கல்யாணம் அஷ்டபி꞉ ஶக்திபி꞉ ஸஹ।।
துர்கேலக்ஷ்மீ ச வாக்தேவி ஸ்வஸ்தாநம் கச்ச பூஜிதே।
ஸம்வத்ஸரே வ்யதீதே து புநராகமநாய வை।।
இமாம் பூஜாம் மயா தேவி யதாஶக்தி உபபாதிதாம்।
ரக்ஷார்தம் த்வம் ஸமாதாய வ்ரஜஸ்வ ஸ்தாநமுத்தமம் ।।
ஶ்ரீதுர்காம் லக்ஷ்மீம் ஸரஸ்வதீம் யதாஸ்தாநம் ப்ரதிஷ்டாபயாமி।
ஶோபநார்தே க்ஷேமாய புநராகமநாய ச।।
நமஸ்காராந் ஸமர்பயாமி',
        'uttiṣṭha devi caṇḍeśi śubhāṃ pūjāṃ pragṛhya।
kuruṣva me hi kalyāṇaṃ aṣṭabhiḥ śaktibhiḥ saha।।
durgelakṣmī ca vāgdevi svasthānaṃ gaccha pūjite।
saṃvatsare vyatīte tu punarāgamanāya vai।।
imāṃ pūjāṃ mayā devi yathāśakti upapāditām।
rakṣārthaṃ tvaṃ samādāya vrajasva sthānamuttamam ।।
śrīdurgāṃ lakṣmīṃ sarasvatīṃ yathāsthānaṃ pratiṣṭhāpayāmi।
śobhanārthe kṣemāya punarāgamanāya ca।।
namaskārān samarpayāmi',
        'Rise, Goddess, Chandeshi, having received this auspicious worship, and do me good together with your eight powers. Durga, Lakshmi and Vagdevi, worshipped, go to your own place, to return again when the year has passed. Take this worship I have offered as I was able, Goddess, for my protection, and go to your highest place. I return Sri Durga, Lakshmi and Saraswati to their places, for what is good, for well-being, and for coming again. I offer my prostrations.',
        'Samvatsare vyatite tu punaragamanaya, "to return when the year has passed". The release is worded as a farewell between people who will see each other again, which is why Vijayadashami is a day for beginning things rather than an ending.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Navaratri Puja p.304, punah poojaa - yathaasthaanam');


